import random

def solve(nums, k):
    def quickselect(nums, k, left=0, right=None):
        if right == None: right = len(nums) - 1
        if len(nums) == 1: return nums[0]
        pivot_index = partition(nums, left, right)
        if k - 1 == pivot_index: return nums[pivot_index]
        elif k - 1 < pivot_index: return quickselect(nums, k, left, pivot_index - 1)
        else: return quickselect(nums, k, pivot_index + 1, right)

    def partition(nums, left, right):
        pivot_index = random.randint(left, right)
        pivot = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] < pivot:
                nums[i], nums[store_index] = nums[store_index], nums[i]
                store_index += 1
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    nums_copy = sorted(nums)
    return quickselect(nums_copy, k)

