def helper(nums, index, memo):
    if index in memo:
        return memo[index]
    max_length = 1
    for i in range(index):
        if nums[index] > nums[i] and helper(nums, i, memo) + 1 > max_length:
            max_length = helper(nums, i, memo) + 1
    memo[index] = max_length
    return memo[index]

