def solve(n, edges):
    uf = UnionFind(n)

    for u, v in edges:
        uf.unite(u, v)

    return any(uf.find(i) == uf.find(j) for i in range(1, n) for j in range(i + 1, n))

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def unite(self, x, y):
        px, py = self.find(x), self.find(y)
        if px != py:
            self.parent[px] = py

def solve(n, edges):
    parent = list(range(n))
    rank = [0] * n

    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        i = find(i)
        j = find(j)
        if i == j:
            return True
        if rank[i] >= rank[j]:
            parent[j] = i
            rank[i] += 1
        else:
            parent[i] = j
            rank[j] += 1
        return False

    for u, v in edges:
        if union(u, v):
            return True

    return False

