def introsort(nums, max_depth = 2 * len(nums).bit_length()):
    def quickselect(low, high):
        if low == high:
            return low
        pivot_index = partition(low, high)
        if k - 1 == pivot_index:
            return nums[k - 1]
        elif k - 1 < pivot_index:
            return quickselect(low, pivot_index - 1)
        else:
            return quickselect(pivot_index + 1, high)

    def partition(low, high):
        pivot = nums[high]
        left = low - 1
        for i in range(low, high):
            if nums[i] < pivot:
                left += 1
                nums[left], nums[i] = nums[i], nums[left]
        nums[left + 1], nums[high] = nums[high], nums[left + 1]
        return left + 1

    k -= 1
    return quickselect(0, len(nums) - 1)

