def heapify(nums):
    n = len(nums)
    for i in range(n // 2 - 1, -1, -1):
        _heapify(nums, i, n)
    return nums

def _heapify(nums, i, n):
    left = 2 * i + 1
    right = 2 * i + 2
    smallest = i
    if left < n and nums[left] < nums[smallest]:
        smallest = left
    if right < n and nums[right] < nums[smallest]:
        smallest = right
    if smallest != i:
        nums[i], nums[smallest] = nums[smallest], nums[i]
        _heapify(nums, smallest, n)

def heapSelection(nums, k):
    heapify(nums)
    for _ in range(len(nums) - k):
        nums[0] = nums[-1]
        nums.pop()
        _heapify(nums, 0, len(nums))
    return nums[0]

