        if self.max_heap:
            if num < self.max_heap.peek():
                self.min_heap.push(num)
                self.sift_up(self.min_heap, self.min_heap.index(num))
            elif num > self.max_heap.peek():
                self.max_heap.push(num)
                self.sift_down(self.max_heap, self.max_heap.index(num))
            else:
                self.max_heap.push(num)
        else:
