def merge(regions):
    to_merge = []
    for region, count in regions:
        i = 0
        while i < len(to_merge):
            curr_region, curr_count = to_merge[i]
            if curr_region == region and curr_count < count:
                to_merge[i] = (region, count)
                return to_merge
            if curr_region > region:
                to_merge.insert(i, (region, count))
                return to_merge
            i += 1
        to_merge.append((region, count))
