def chunked_sort(nums, k):
    chunks = [nums[i:i+k] for i in range(0, len(nums), k)]
    for i in range(0, len(chunks), 2):
        chunks[i] = sorted(chunks[i])
        if i + 1 < len(chunks):
            chunks[i+1] = sorted(chunks[i+1], reverse=True)
    for i in range(len(chunks) - 1, 0, -1):
        chunks[i-1] = combine(chunk for chunk in zipLongest(*chunks[i-1:i]))
