def combine(chunks):
    sorted_chunk = sorted(chunks)
    heapq.heapify(sorted_chunk)
    new_chunk = []
    while len(new_chunk) != len(chunks[0]):
        new_chunk.append(heapq.heappop(sorted_chunk))
