def _maxheapify(nums, i, heap):
    while True:
        largest = i
        left, right = 2 * i + 1, 2 * i + 2
        if left < len(nums) and nums[left] > nums[largest]:
            largest = left
        if right < len(nums) and nums[right] > nums[largest]:
