def strmatch(haystack: str, needle: str) -> int:
    """ Returns true whenever a match is found for which the needle appears in
    the haystack and the ending position of the match for the needle is
    <= i, where i is the position in the haystack where the search started. 
    This function does not scan beyond that position. However, if the previous
    search found no match and only the first character of the needle matches
    the first character of the haystack, and the previous & next characters of 
    haystack also match the corresponding characters of the needle, the search 
    looks ahead in the haystack for the next match. If there is a match, the 
    method backtracks and delimits the match to make sure that the dissected
    match ends Here. """
    diff = len(needle)
    i = 0
    while diff > -1:
        i += diff
        skip = 1
        if i >= len(haystack):
            return -1
        if haystack[i: i + len(needle)] != needle:
            skip = 2
            i += 1
        if diff == 0:
            return i
        diff = find_skips(haystack, i + 1, needle) - skip
        if diff == 0:
            i += 1
        diff = max(0, diff - 1)


def find_skips(haystack: str, start: int, needle: str) -> int:
