def rabinKarp(string, pattern):
    M = 998244353  # A prime number to prevent overflows
    d = 256  # Number of possible characters in lowercase letters
    N = len(string)
    K = len(pattern)
    p = 0  # Hash value of pattern
    t = 0  # Hash value of substring being considered
    h = 1  # Hash value of substring of length K-1

    # Compute h as d^(K-1) % M
    for _ in range(K-1):
        h = (h*d) % M

    # Compute the hash values of pattern and first window of string
    for i in range(K):
        p = (d*p + ord(pattern[i])) % M
        t = (d*t + ord(string[i])) % M

    # Slide the pattern over string and compare
    occurrences = []
    for i in range(N-K+1):
        if p == t:
            match = True
            for j in range(K):
                if string[i+j] != pattern[j]:
                    match = False
                    break
            if match:
                occurrences.append(i)
        if i < N-K:
            t = (d*(t - ord(string[i])*h) + ord(string[i+K])) % M
            if t < 0:
                t += M

    return occurrences


