def multiply_matrices(a, b, modulo):
    c = [[0, 0], [0, 0]]
    c[0][0] = (a[0][0] * b[0][0] + a[0][1] * b[1][0]) % modulo
    c[0][1] = (a[0][0] * b[0][1] + a[0][1] * b[1][1]) % modulo
    c[1][0] = (a[1][0] * b[0][0] + a[1][1] * b[1][0]) % modulo
    c[1][1] = (a[1][0] * b[0][1] + a[1][1] * b[1][1]) % modulo
    return c

def power(matrix, n, modulo):
    if n == 0 or n == 1:
        return
    if n % 2 == 0:
        half_pow = power(matrix, n // 2, modulo)
        result = multiply_matrices(half_pow, half_pow, modulo)
    else:
        half_pow = power(matrix, n // 2, modulo)
        half_pow = multiply_matrices(half_pow, half_pow, modulo)
        result = multiply_matrices(half_pow, matrix, modulo)
    return result

