def main(nums, k):
    freqs = Counter(nums)
    min_val, max_val = min(freqs.values()), max(freqs.values())
    freqs = helper_operation(list(freqs.values()))
    if min_val > freqs[k-1]:
        return []
    if freqs[-1] == freqs[-2]:
        major = freqs[-1]
        return [num for num in nums if freqs[num] == major]
    while max_val > freqs[k-1] and freqs[k-1] < freqs[k]:
        val2 = find_major(max_val, freqs[k-1])
        if max_val <= val2 <= freqs[k-1]:
            right = freqs.index(max_val)
            return [num for num, freq in freqs.items() if freq == val2]
        min_val = freqs[k-1]
        left = freqs.index(min_val)
        major = helper_binary_search(left, right, freqs, k)
        if freqs[major] == val2:
            return [num for num, freq in freqs.items() if freq == val2]
