            return []
        val2 = find_major(max_val, freqs[-1])
        if max_val <= val2 <= freqs[k-1]:
            right = freqs.index(max_val)
            return [num for num, freq in freqs.items() if freq == val2]
        max_val = helper_binary_search(left, right, freqs, k)
    while freqs[k] != freqs[k-1]:
        val2 = find_major(freqs[k-1], freqs[k])
        right = freqs.index(freqs[k])
        left = freqs.index(freqs[k-1])
        major = helper_binary_search(left, right, freqs, k)
        if freqs[major] == val2:
            return [num for num, freq in freqs.items() if freq == val2]
        if major > 0:
            return [num for num, freq in freqs.items()]
        return [num for num, freq in freqs.items()]
    return solve(nums, k)

