def solve(nums, target):
    first, last = bin_search(nums, target), bin_search(nums, target, True)
    return [first, last] if 0 <= first <= len(nums) - 1 and first == last else [-1, -1]

def bin_search(nums, target, last=False):
    low, high = 0, len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            if last:
                if mid == len(nums) - 1 or nums[mid + 1] != target:
                    return mid
                high = mid
            else:
                if mid == 0 or nums[mid - 1] != target:
                    return mid
                low = mid
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

