def height(i, j, table):
    return j - i + 1 >= len(table) and table.index(min(table)) or table[i]

def length(i, j, table):
    return min(height(i, j, table), table[j] - table[i] + 1)

def solve_recursive(l, r, table):
    if l == r:
        return 1
    elif l + 1 == r:
        return max(solve_recursive(l, r - 1, table), 1)
    else:
        lo, hi = l, r
        while lo < hi:
            mid = lo + hi + 1 >> 1
            if length(l, mid, table) <= (r - mid + 1) // 2:
                lo = mid
            else:
                hi = mid - 1
        return max(solve_recursive(l, lo, table), 1 + solve_recursive(lo + 1, r, table))

