    def search(nums, target, find_first):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                if find_first and (mid == 0 or nums[mid - 1] < target):
                    return mid
                if not find_first and (mid == len(nums) - 1 or nums[mid + 1] > target):
                    return mid
                right = mid - 1 if find_first else mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    first = search(nums, target, True)
    if first == -1:
        return [-1, -1]
    last = search(nums, target, False)
    return [first, last]

