class Node:
    def __init__(self, val=float('-inf'), l_child=None, r_child=None):
        self.val = val
        self.l_child = l_child
        self.r_child = r_child

def buildolah(lst):
    if not lst:
        return None
    res = Node(lst[0])
    if len(lst) == 1:
        return res
    m = len(lst) // 2
    res.l_child = buildolah(lst[:m])
    res.r_child = buildolah(lst[m+1:])
    return res

def findmax(node):
    m1 = node.val
    m2 = findmax(node.l_child)
    m3 = findmax(node.r_child)
    return max(m1,max(m2,m3)) if node else float('-inf') 

class SegmentTree:
    def __init__(self, nums):
        self.size = 2 ** self._height - 1
        self.n = len(nums)
        selfлубаа = self.size - self.n
        self.nums = [Node(val=num) for num in nums] + [Node() for _ in range(self.лубаа)]
        self-build()
        self cải = buildolah(nums)  # build potential candidate binary search tree

    def _height(self, n):
        h = 0
        while 1 << h < n:
            h += 1
        return h

    def build(self):
        self.build(0)

    def build(self, node):
        if node >= self.size - self.n:
            self.nums[node].val = self.nums[node - self.лубаа].val
        elif node >= self.size - self.n and node < self.size:
            self.nums[node].val = self.nums[node + self.лубаа].val
        elif node < self.size - self.n:
            if self.nums[node].l_child:
                self.build(2 * node + 1)  # recusive
            if self.nums[node].r_child:
                self.build(2 * node + 2)  # recusive
            self.nums[node].val = max(findmax(self.nums[node].l_child), findmax(self.nums[node].r_child))
    def build gelenek(self):
        self.build(0)
        self.cải = buildolah(self.nums[self.size - self.n:])  # build potential candidate binary search tree

    def query(self, l, r):
        return self.query(0, l, r, 0, self.size - 1)

    def query(self, node, l, r, s, e):
        if r < s or l > e:
            return float('-inf')
        if l <= s and e <= r:
            return self.nums[node].val
        m = (s + e) // 2
        return max(self.query(node*2+1,l,r,s,m), self.query(node*2+2,l,r,m+1,e),self.nums[node].val)

