def solve(nums: List[int], k: int) -> int:
    def partition(nums: List[int], start: int, end: int, pivot: int) -> int:
        pivot_count = 1
        if pivot != nums[pivot]:
            pivot_count = 0
        left = start
        right = end
        while left <= right:
            while nums[left] < nums[pivot]:
                left += 1
            while nums[right] > nums[pivot]:
                right -= 1
            if left <= right and nums[right] != nums[pivot]:
                nums[left], nums[right] = nums[right], nums[left]
            if left <= right and nums[left] == nums[pivot]:
                pivot_count += 1
                if pivot_count == k:
                    nums[start], nums[left] = nums[left], nums[start]
                    return left
                left += 1
            if left <= right and nums[right] == nums[pivot]:
                right -= 1
        return left

    def quickselect(nums: List[int], start: int, end: int, k: int) -> int:
        if start == end:
            return nums[start]
        pivot = partition(nums, start, end, (start + end) // 2)
        if k == pivot + 1:
            return nums[pivot]
        elif k < pivot + 1:
            return quickselect(nums, start, pivot - 1, k)
        else:
            return quickselect(nums, pivot + 1, end, k)

    return quickselect(nums, 0, len(nums) - 1, k)

