def kth_smallest(nums, k):
    pool = sorted(set(nums))
    while True:
        pivot = pool[len(pool) // 2]
        lesser = [x for x in pool if x < pivot]
        equal = [x for x in pool if x == pivot]
        greater = [x for x in pool if x > pivot]

        if len(pool) - len(lesser) == k - 1:
            return pivot
        if k - 1 < len(lesser):
            pool = lesser
        elif k - 1 > len(lesser) + len(equal):
            pool = greater
        else:
            return pivot

