def solve(nums):
    def find_max_crossing_left(array, low, mid):
        best = mid
        value = array[mid]
        for i in range(mid-1, low-1, -1):
            if array[i] < value:
                value = array[i]
                best = i
        return best

    def find_max_crossing_right(array, mid, high):
        best = mid
        value = array[mid]
        for i in range(mid+1, high+1):
            if array[i] < value:
                value = array[i]
                best = i
        return best

    def partition(array, low, high):
        value = array[find_max_crossing_right(array, low, high)]
        j = find_max_crossing_left(array, low, high)
        index = low - 1
        while j <= high:
            array[index+1] = array[j]
            index += 1
            j += 1
        array[index + 1] = value
        return index + 2

    def merge_sort(array, low, high):
        if low < high:
            mid = (low + high) // 2
            left_subseq = merge_sort(array, low, mid-1)
            right_subseq = merge_sort(array, mid, high)
            merged = partition(array, low, high)
            return left_subseq + max(right_subseq - merged + 1, 1)
        return 1

    return merge_sort(nums, 0, len(nums) - 1)

