def solve(n, prerequisites):
    deps = defaultdict(set)
    indep = defaultdict(int)
    for a, b in prerequisites:
        indep[a] += 1
        deps[b].add(a)
    queue, global_id = deque(), count()
    for i in range(n):
        if not indep[i]:
            queue.append(next(global_id))
    def paired(x):
        yield x
        while True:
            x = next(global_id)
            for a in deps(x):
                indep[a] -= 1
                if not indep[a]:
                    queue.append(x)
                    yield x
    order = []
    if not queue:
        return []
    while queue:
        try:
            order.append(next(paired(queue.popleft())))
        except StopIteration:
            return []
    return order

