        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] == target:
                right = mid
            elif nums[mid] > target:
                right = mid
            else:
                left = mid + 1
        if below and left > 0 and nums[left - 1] == target:
            return left - 1
        return left

    first = binary_search(nums, target)
    if first == len(nums) or nums[first] != target:
        return [-1, -1]
    last = binary_search(nums, target, True) - 1
    return [first, last]

