class Treap:
    def __init__(self, t):
        self.t = t
        self.root = None

    def LEFT rot(self, u):
        T = self.root
        v = u.right
        u.right = v.left
        v.left = u
        T[self.left(v, u)] = v
        T[self.right(v, u)] = u.right
        return v

    def RIGHT rot(self, u):
        T = self.root
        v = u.left
        u.left = v.right
        v.right = u
        T[self.left(u, v)] = u
        T[self.right(u, v)] = v.right
        return v

    def put(self, T, k, v):
        if not T:
            T[k] = v
            return Treap(T), 1
        cmp = 1 if v < T[k] else -1 if v > T[k] else 0
        if cmp < 0:
            T, x = self.put(T[self.left(T, k)], k, v)
            Treap.__setitem__(T, self.left(k, k), x)
        elif cmp > 0:
            T, x = self.put(T[self.right(T, k)], k, v)
            Treap.__setitem__(T, self.right(k, k), x)
        else:
            T[k] = v
            return Treap(T), 1 + (
                Treap.__getitem__(self, self.left(T, k)) or 0) + (
                Treap.__getitem__(self, self.right(T, k)) or 0)
        return Treap(T), Treap.__getitem__(self, k) + x

    def GET(self, k):
        T = self.root
        while T:
            cmp = 1 if k < T[k] else -1 if k > T[k] else 0
            if cmp < 0:
                T = T[self.left(k, k)]
            elif cmp > 0:
                T = T[self.right(k, k)]
            else:
                return T[k]

    def __getitem__(self, k):
        T = self.root
        while T:
            lhs, rhs = self.left(k, k), self.right(k, k)
            if lhs and rhs:
                Test = (Treap.__getitem__(self, lhs),
                        Treap.__getitem__(self, rhs),
                        Treap.__getitem__(self, k))
                if Test == (1, 2, 0) or Test == (1, 1, 2) or Test == (2, 1, 2):
                    return 0
                lhs, rhs = max([lhs, rhs], key=lambda x:
                    Treap.__getitem__(self, x) if x else 0)
            k = lhs if k < T[k] else rhs if k > T[k] else k
            T = T[k]
        return None

    def __setitem__(self, k, v):
        self.root, _ = self.put({}, k, v)

