def heapify(lst, idx, end):
    if idx >= end:
        return
    left = 2 * idx + 1
    right = 2 * idx + 2
    max_idx = idx
    if left <= end and lst[left][0] > lst[max_idx][0]:
        max_idx = left
    if right <= end and lst[right][0] > lst[max_idx][0]:
        max_idx = right
    if max_idx != idx:
        lst[idx], lst[max_idx] = lst[max_idx], lst[idx]
        heapify(lst, max_idx, end)

