def solve(nums, target):
    def search(nums, l, r, target, mode=True):
        if l > r: return -1, -1 if mode else None
        m = (l + r) >> 1
        prev, nxt = m, m
        if nums[m] == target:
            if mode: return m, m
            while m-1 >= l and nums[m-1] == target: m -= 1
            return prev, m
        if nums[m] < target:
            prev, nxt = search(nums, m+1, r, target, mode)
        else:
            prev, nxt = search(nums, l, m-1, target, mode)
        if m > prev: prev, nxt = search(nums, prev+1, m-1, target, False)
        if m < nxt: prev, nxt = search(nums, m+1, nxt-1, target, False)
        return prev, nxt
    return search(nums, 0, len(nums)-1, target)

