def solve(nums, k):
    def quickselect(nums, k, left, right):
        if len(nums) == 1:
            return nums[0]
        pivot_index = partition(nums, left, right)
        if pivot_index == k - 1:
            return nums[pivot_index]
        elif pivot_index > k - 1:
            return quickselect(nums, k, left, pivot_index - 1)
        else:
            return quickselect(nums, k, pivot_index + 1, right)

    def partition(nums, left, right):
        pivot = nums[random.randint(left, right)]
        i = left
        j = right
        while i <= j:
            while nums[i] < pivot:
                i += 1
            while nums[j] > pivot:
                j -= 1
            if i <= j:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
                j -= 1
        return i

    random.shuffle(nums)
    return quickselect(nums, k, 0, len(nums) - 1)

