def heapify_and_pop(heap, index):
    while True:
        smallest = index
        left = 2 * index + 1
        right = 2 * index + 2
        if left < len(heap) and heap[left] < heap[smallest]:
            smallest = left
        if right < len(heap) and heap[right] < heap[smallest]:
            smallest = right
        if smallest == index:
            break
        heap[index], heap[smallest] = heap[smallest], heap[index]
        index = smallest

