    phi = [len(is_primeprime) - 1] * len(is_primeprime)
    for i, p in enumerate(is_primeprime):
        phi[i] = phi[i] * phi[i - 1]
    table = [[-1] * len(is_primeprime) for _ in range(exp + 1)]
    table[0] = is_primeprime
    for i in range(1, exp + 1):
        curr = [-1] * len(is_primeprime)
        for j, bit in enumerate(is_primeprime):
            if bit:
                t = table[i - 1][j]
                if t == -1:
                    curr[j] = 0
                else:
                    curr[j] = (phi[t] * j) % len(is_primeprime)
        table[i] = curr
    return table


