def find_median_of_medians(nums):
    if not nums:
        return None
    if len(nums) == 1:
        return nums[0]

    medians = []
    for i in range(0, len(nums), 5):
        chunk = nums[i:i+5]
        if len(chunk) == 1:
            medians.append(chunk[0])
        else:
            medians.append(select_key(chunk, int(len(chunk)/2)))

    return find_median_of_medians(medians)

def select_key(nums, k):
    pivot = find_median_of_medians(nums)
    lhs = [x for x in nums if x < pivot]
    rhs = [x for x in nums if x > pivot]
    pivot_count = 1
    while rhs and pivot_count <= k:
        if len(lhs) >= 5:
            lhs_pivot = find_median_of_medians(lhs)
            lhs = [x for x in lhs if x < lhs_pivot]
        else:
            select_count = sum(1 for x in lhs if x < pivot)
            if select_count >= k-pivot_count:
                return pivot
            else:
                pivot_count += select_count
    if k - pivot_count == len(rhs):
        return pivot
    return select_prefix(rhs, k-pivot_count)

def select_prefix(nums, k):
    n = len(nums)
    low, high = 1, n
    while low != high:
        mid = (low + high) // 2
        if sum(1 for x in nums[:mid] if x < nums[mid-1]) + 1 < k:
            low = mid + 1
        else:
            high = mid
    return nums[low-1]

