from typing import List

def binary_search(nums: List[int], target: int) -> int:
    """Binary search helper function to find i such that nums[i] equals the target."""
    low, high = 0, len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return low


