    """Find two indices i and j such that nums[i] + nums[j] == target."""
    # Create a copy of the input list for modification
    copy = sorted((num, i) for i, num in enumerate(nums))
    nums_map = {num: i for num, i in copy}

    # Binary search for i
    j = binary_search(nums, target)
    # We want i < j as per the specification
    while j < len(nums) and copy[j][0] + copy[j-1][0] >= target:
        j -= 1
    # Check if j is valid before accessing
    if j > 0:
        return [copy[j-1][1], copy[j][1]]
    else:
        return []

