def prevGreater(nums):
    stack = []
    result = [-1] * len(nums)
    for i, num in enumerate(nums):
        while stack and nums[stack[-1]] < num:
            result[stack.pop()] = i
        stack.append(i)
    return result

def prevLesser(nums):
    stack = []
    result = [len(nums)] * len(nums)
    for i, num in enumerate(nums):
        while stack and nums[stack[-1]] > num:
            result[stack.pop()] = i
