        pi, pj = find_parent(parent, i), find_parent(parent, j)
        if pi != pj:
            if rank[pi] > rank[pj]:
                parent[pj] = pi
            else:
                parent[pi] = pj
                if rank[pi] == rank[pj]:
                    rank[pj] += 1

