import networkx as nx

class IntervalGraph:
    def __init__(self, intervals):
        self.G = nx.DiGraph()
        self.intervals = intervals
        self.node2interval = defaultdict(list)
        self.add_nodes()

    def add_nodes(self):
        for i, (start, end) in enumerate(self.intervals):
            self.G.add_node(i)
            self.node2interval[start].append((i, 0))  # start
            self.node2interval[end].append((i, 1))  # end

    def get_start_nodes(self):
        return [i for b in self.node2interval.values() for i, flag in b if flag == 0]

    def get_end_nodes(self):
        return [i for b in self.node2interval.values() for i, flag in b if flag == 1]


def solve(intervals):
    graph = IntervalGraph(intervals)
    start_nodes = graph.get_start_nodes()
    end_nodes = graph.get_end_nodes()

    graph.G.add_edges_from((i, j) for i in start_nodes for j in end_nodes)

    dp = {}
    for node in nx.topological_sort(graph.G):
        dp[node] = (node, -1)
        for neighbor in graph.G[node]:
            if dp[neighbor][1] < dp[node][1]:
                dp[node] = (dp[neighbor][0], neighbor)

    cycles = set()
    for node in nx.topological_sort(graph.G):
        if dp[node][1] >= 0:
            cycle = []
            while node >= dp[node][0]:
                cycle.append(node)
                node = dp[node][1]
            cycles.add(tuple(cycle))

    return len(cycles)

