    intervals = [(i, i + 1) if j == 1 else (j, k) for i, (j, k) in enumerate(intervals) for _ in range(k - j + 1)]
    intervals.sort(key=lambda x: x[1])

    tree = {}

    sizes = {}
    for i, u in enumerate(intervals):
        sizes[i] = 1
        if u[0] not in tree:
            tree[u[0]] = set()
        if u[1] not in tree:
            tree[u[1]] = set()
        tree[u[0]].add(u[1])
        tree[u[1]].add(u[0])

    ans = float('inf')
    for i, u in enumerate(intervals):
        subgraph = tree[u[0]]
        subgraph.remove(u[1])
        if u[1] in subgraph:
            subgraph.remove(u[1])
        longest = 0
        for v in subgraph:
            if v in tree:
                longest = max(longest, longest_path(v))
        for u1 in tree:
