    m, n = a.shape
    p, q = b.shape
    c = a.__class__.zeros((m, q))

    for i in range(m):
        for j in range(q):
            if a.shape[1] == p:
                for k in range(p):
                    c[i, j] += a[i, k] * b[k, j]
            else:
                c[i, j] = sum(a[i, k] * b[k, j] for k in range(min(a.shape[1], p)))

    return c


class Matrix:
    def __init__(self, lst):
        self.lst = lst

    def __add__(self, other):
        return Matrix(assert_equals_shape(self, other))

    def __sub__(self, other):
        return Matrix.assert_equals_shape(self, other) and Matrix([x - y for x, y in zip(self.lst, other.lst)])

    def __rsub__(self, other):
        return Matrix.assert_equals_shape(self, other) and Matrix([y - x for x, y in zip(self.lst, other.lst)])

    def __mul__(self, other):
        return multiply_matrices(self, other)

    def __rmul__(self, other):
        return multiply_matrices(other, self)

    def __eq__(self, other):
        return self.lst == other.lst

    @staticmethod
    def zeros(shape):
        if len(shape) != 2 or not isinstance(shape[0], int) or not isinstance(shape[1], int):
            raise ValueError('invalid shape for zeros')
        if shape[0] == shape[1] == 0:
            return Matrix([[0]])
        elif shape[0] == 0 or shape[1] == 0:
            raise ValueError('all leading and trailing dimensions must be zero')
        else:
            return Matrix(matrix_zeros(shape))

    @staticmethod
    def identity(n):
        return Matrix.idn(n)

    @staticmethod
    def idn(n):
        return Matrix(matrix_eye(n))

    @staticmethod
    def assert_equals_shape(first, second):
        return isinstance(first, Matrix) and isinstance(second, Matrix) and first.lst.__len__() == second.lst.__len__() and first.lst.__len__() == list(map(int, first.lst[0])).__len__()

    def visual(self):
        for y in range(list(map(int, self.lst[0])).__len__()):
            row = ''
            for x in range(len(self.lst)):
                row += '{:>4d}'.format(self.lst[x][y])
            print(row)

    def logs(self):
        for x in range(self.lst.__len__()):
            print('[', end='')
            for y in range(list(map(int, self.lst[0])).__len__()):
                print(self.lst[x][y], end='')
                if y != list(map(int, self.lst[0])).__len__() - 1:
                    print(',', end='')
            print(']')


def fast_doubling(n):
    if n == 0:
        return Matrix([[1]])
    elif n % 2 == 0:
        half = fast_doubling(n // 2)
        return half * half
    else:
        half = fast_doubling((n - 1) // 2)
        return half * half * Matrix([[1, 1], [1, 0]])


def matrix_zeros(shape):
    result = []
    for _ in range(shape[0]):
        result.append([0] * shape[1])
    return result


def matrix_eye(n):
    result = []
    for i in range(n):
        row = [0] * n
        row[i] = 1
        result.append(row)
    return result


def fib_matrix(i):
    if i == 0:
        return Matrix([[1, 1], [1, 0]])
    elif i % 2 == 0:
        half = fib_matrix(i // 2)
        return half * half
    else:
        nth = fib_matrix((i - 1) // 2)
        return nth * nth * Matrix([[1, 1], [1, 0]])


def get_fib(n):
