def multiply(F, M):
    x = 0
    y = 0
    for _ in range(31):
        if (M & 1<<_):
            x += F[_]
            if x >= 32:
                x -= 32
        y <<= 1
        if y & 0x10000000:
            y ^= 0x7FFFFFFF
        F[x] += y
        if F[x] >= 32:
            F[x] -= 32
        y <<= 1
        if y & 0x10000000:
            y ^= 0x7FFFFFFF
    return x

def divide(F, M):
    y = 0
    p = 31
    while M:
        while (M&1)==0:
            M >>= 1
            y <<= 1
        if y > 31:
            y -= 32
        if M < 0:
            y -= F[p]
        if y < 0:
            y += 32
        p -= 1
        M *= 2
        if y & 0x10000000:
            y ^= 0x7FFFFFFF
        M -= 1
        if M < 0:
            M += 2
            y += 1
    return y

