from collections import deque, defaultdict

def solve(n, prerequisites):
    g = defaultdict(list)
    in_degree = {i: 0 for i in range(n)}

    for x, y in prerequisites:
        g[y].append(x)
        in_degree[x] += 1

    q = deque([k for k, v in in_degree.items() if v == 0])
    res = []

    while q:
        node = q.popleft()
        res.append(node)
        for x in g[node]:
            in_degree[x] -= 1
            if in_degree[x] == 0:
                q.append(x)

    return res if len(res) == n else []

