def solve(n, prerequisites):
    graph = defaultdict(list)
    indegree = [0] * n

    for a, b in prerequisites:
        graph[b].append(a)
        indegree[a] += 1

    def has_cycle(node):
        visited = set()
        stack = deque([node])
        while stack:
            v = stack.pop()
            if v in visited:
                return True
            visited.add(v)
            for x in graph[v]:
                stack.append(x)
        return False

    if has_cycle(n - 1):
        return []

    order = []
    q = deque([i for i in range(n) if indegree[i] == 0])
    while q:
        node = q.popleft()
        order.append(node)
        for x in graph[node]:
            indegree[x] -= 1
            if indegree[x] == 0:
                q.append(x)

    return order if len(order) == n else []

