def longest_path(graph):
    n = len(graph)
    dp = [[-1, 0] for _ in range(n)]
    for i in range(n):
        if dp[i][0] == -1:
            que = deque([i])
            maxdepth = 0
            while que:
                v = que.popleft()
                if dp[v][0] == -1:
                    dp[v][0] = maxdepth
                    dp[v][1] = sum(1 for u in graph[v] if dp[u][0] != -1)
                if dp[v][1]:
                    maxdepth += 1
                    for u in graph[v]:
                        if dp[u][0] == -1:
                            que.append(u)
                else:
                    maxdepth = max(maxdepth, dp[v][0] + 1)
                    for u in graph[v]:
                        if dp[u][0] != -1:
                            maxdepth = max(maxdepth, dp[u][0] + 1)
    maxid = max((dp[i][0] + dp[i][1] for i in range(n)), default=-1)
    result = []
    for i in range(n):
        if dp[i][0] + dp[i][1] == maxid:
            result.append(i)
    return result

