    if not graph:
        return [x for x in range(n)]
    order = solve(n, graph)
    if not order:
        return []
    for i in range(n):
        if i in order:
            order.remove(i)
            return [i] + toposort(n, {{j for j in graph[i]} - {i} for i in graph})
    return []

