    graph = defaultdict(set)
    for a, b in prerequisites:
        graph[b].add(a)
    forward = toposort(n, graph)
    if not forward:
        return []
    backward = toposort(n, {u for u, vs in graph.items() for v in vs} | {i: {j for j in graph[i]}  for i in range(n)})
    if not backward:
        return []
    forward.reverse()
    graph = defaultdict(set)
    for v in forward:
        for u in backward:
            if v < u:
                graph[u].add(v)
    return longest_path(graph)

