        self.graph[b].append(a)
        self.in_degree[a] += 1

    def solve(self):
        queue = deque([i for i in range(self.n) if self.in_degree[i] == 0])

        while queue:
            node = queue.popleft()
            self.top_sort.append(node)

            for neighbor in self.graph[node]:
                self.in_degree[neighbor] -= 1
                if self.in_degree[neighbor] == 0:
                    queue.append(neighbor)

        return self.top_sort if len(self.top_sort) == self.n else []

