    size = 0

    def add_task(i):
        if dp[size][i] == 0:
            size += 1
            dp.append(dp[size - 1][:])
            dp[size][i] = size

    for a, b in sorted(prerequisites, key=lambda x: x[0]):
        if dp[a] < dp[b]:
            return []
        if not dp[b]:
            add_task(b)
        for i in range(n):
            if dp[a] < dp[i] and (not dp[i]):
                add_task(i)
                if a == i: dp[size - 1][i] = size - 1
        if dp[a] and dp[a][b]:
            dp[a][b] = size
        elif not dp[a]:
            add_task(a)
            dp[a][b] = size
        elif dp[b] > dp[a]:
            return []

    return [i - 1 for i in sorted((j + 1 for j in map(max, dp)))]

