    max_degree_node = None

    for i in range(n):
        if indegree[i] == 0:
            max_degree = 1
            max_degree_node = i
        elif indegree[i] > max_degree and indegree[i] > 0:
            max_degree = indegree[i]
            max_degree_node = i

    if max_degree_node is None:
        return []

