    max_degree_graph = defaultdict(list)

    for a, b in prerequisites:
        if a == max_degree_node:
            for i in graph[b]:
                if i != max_degree_node:
                    max_degree_graph[a].append(i)

    for i in range(n - 1):
        x = heappop(max_degree_order)

        for y in max_degree_graph[x]:
            del graph[y][graph[y].index(x)]  # remove duplicates

        if graph[x]:
            for y in graph[x]:
                indegree[y] -= 1
                if indegree[y] == 0:
                    max_degree_graph[x].append(y)
                    heappush(max_degree_order, y)

        max_degree_graph[x].clear()

    result = []

