def solve(intervals):
    def can_insert(new_interval, added_intervals):
        prev_end = added_intervals[-1][1] if added_intervals else -1
        return new_interval[0] > prev_end

    def single_sweep(intervals, removed_intervals):
        swept_intervals = []
        for new_interval in intervals:
            if not removed_intervals or can_insert(new_interval, removed_intervals):
                swept_intervals.append(new_interval)
                if removed_intervals:
                    removed_intervals.sort()  # Sort the removed intervals
                    i = 0
                    while i < len(removed_intervals) - 1 and removed_intervals[i][1] >= new_interval[0]:
                        to_remove = removed_intervals.pop(i)
                        if to_remove[1] > new_interval[1]:
                            new_interval = [new_interval[0], to_remove[1]]
                        swept_intervals[-1] = new_interval
                    if removed_intervals and removed_intervals[0][0] <= new_interval[1]:
                        removed_intervals.insert(0, [removed_intervals[0][0], new_interval[1]])
            else:
                removed_intervals.append(new_interval)
        return swept_intervals, removed_intervals

    times = [interval[0] for interval in intervals] + [interval[1] for interval in intervals] + [-1]
    sorted_times = sorted(set(times))

    added_intervals = []
    removed_intervals = []

    for t in sorted_times:
        new_added_intervals = [interval for interval in intervals if interval[0] == t]
        added_intervals, removed_intervals = single_sweep(new_added_intervals, removed_intervals)
        intervals = [interval for interval in intervals if interval not in new_added_intervals]

    return added_intervals

