    def _find_overlapping(self, node, start, end):
        if node is None:
            return []
        intervals = []
        if start <= node.start and end >= node.start:
            intervals.extend(self._find_overlapping(node.left, start, end))
            intervals.extend(self._find_overlapping(node.right, start, end))
            return intervals + [min(node.start, start), max(node.end, end)]
        elif start < node.end:
            intervals.extend(self._find_overlapping(node.left, start, end))
            if start <= node.start and node.start <= end:
                intervals.append([node.start, max(node.end, end)])
            return intervals + self._find_overlapping(node.right, start, end)
        else:
            return self._find_overlapping(node.left, start, end) + self._find_overlapping(node.right, start, end)

