def solve(intervals):
    """Merges overlapping intervals."""
    def merge(left, right):
        """Merge the interval trees on the left and right subtree."""
        if not left:
            return right
        if not right:
            return left
        if left.start < right.start:
            merged = merge(left, right.right)
            left.right = merged
            return left
        else:
            merged = merge(left.left, right)
            left.left = merged
            return left

    def interval_to_node(interval):
        """Convert an interval to a node."""
        node = IntervalNode(interval[0], interval[1])
        middle = (interval[0] + interval[1]) // 2
        if middle == interval[1]:
            middle -= 1
        if middle < 0:
            return node
        node.left = interval_to_node([interval[0], middle])
        node.right = interval_to_node([middle + 1, interval[1]])
        if node.left and node.left.end >= node.start:
            node.start = node.left.start
            node.end = merge(node.left, node.right).end
            node.left = None
            node.right = None
        return node

    root = interval_to_node(min(intervals, key=lambda x: x[1])[1:])
    merged_intervals = []
    def inorder(node):
        """Perform an in-order traversal of the interval tree."""
        if node:
            inorder(node.left)
            if node.left or node.right:
                if node.start == node.end:
                    start, end = node.start, node.start
                elif node.left:
                    start = node.left.end if node.left else node.start
                    end = node.end
                else:
                    start = node.start
                    end = node.end
                merged_intervals.append([start, end])
            inorder(node.right)

    inorder(root)
    return merged_intervals

from collections import defaultdict, deque

def solve(n, prerequisites):
    def is_cyclic(node, visited):
        if (node, 1) in visited:
            return False
        visited.add((node, 0))
        for next_node in graph[node]:
            if (next_node, 1) not in visited:
                if is_cyclic(next_node, visited):
                    return True
            elif (next_node, 0) in visited:
                return True
        visited.remove((node, 0))
        visited.add((node, 1))
        return False

    graph = defaultdict(list)
    indegree = [0] * n
    for a, b in prerequisites:
        graph[b].append(a)
        indegree[a] += 1

    if any(is_cyclic(node, set()) for node in range(n)):
        return []

    dominoes = deque([node for node in range(n) if indegree[node] == 0])
    order = []
    while dominoes:
        node = dominoes.popleft()
        order.append(node)
        for next_node in graph[node]:
            indegree[next_node] -= 1
            if indegree[next_node] == 0:
                dominoes.append(next_node)
    return order if len(order) == n else []

