class IntervalTree:
    def __init__(self):
        self.root = None

    def _insert_node(self, node, new_node):
        if new_node is None:
            return node
        if node is None:
            return new_node
        if new_node.start <= node.end:
            node.left = self._insert_node(node.left, new_node)
            return node
        node.right = self._insert_node(node.right, new_node)
        return node

    def _find_node(self, node, target_start, target_end):
        if node is None or node.start >= target_end or node.end <= target_start:
            return None
        if node.start == target_start and node.end == target_end:
            return node
        candidate = self._find_node(node.left, target_start, target_end)
        if candidate:
            return candidate
        return self._find_node(node.right, target_start, target_end)

    def _merge_nodes(self, node, interval):
        node.start = min(node.start, interval.start)
        node.end = max(node.end, interval.end)
        return node

    def build(self, intervals):
        intervals.sort(key=lambda x: x[0])
        self.root = None
        for interval in intervals:
            self.root = self._insert_node(self.root, IntervalTreeNode(*interval))

    def merge(self):
        if self.root is None:
            return []
        result = []
        stack = [self.root]
        while stack:
            node = stack.pop()
            candidate = self._find_node(node, node.start, node.end)
            if candidate:
                if candidate is node:
                    result.append([node.start, node.end])
            if node.left:
                stack.append(node)
                stack.append(node.left)
            if node.right:
                stack.append(node)
                stack.append(node.right)
        merged_intervals = []
        for i in range(len(result) - 1):
            if result[i][1] >= result[i+1][0]:
                merged_start = min(result[i][0], result[i+1][0])
                merged_end = max(result[i][1], result[i+1][1])
                merged_intervals.append([merged_start, merged_end])
                i += 1
            else:
                merged_intervals.append(result[i])
        return merged_intervals

