        if node.left:
            self.bit.update(node.left.start, 1)
            self.bit.update(node.left.end + 1, -1)
        if node.right:
            self.bit.update(node.right.start, 1)
            self.bit.update(node.right.end + 1, -1)

    def _merge(self, left, right):
        result = None
        if not left:
            result = right
        elif not right:
            result = left
        else:
            result = Node(min(left.start, right.start), max(left.end, right.end))
            if left.end >= right.start:
                if left.right:
                    self.bit.update(left.right.start, -1)
                    self.bit.update(left.right.end + 1, 1)
                left.right = self._merge(left.right, right)
                self._push_node(left)
            else:
                if right.left:
                    self.bit.update(right.left.start, -1)
                    self.bit.update(right.left.end + 1, 1)
                right.left = self._merge(left, right.left)
                self._push_node(right)
        return result

    def insert(self, node):
        node_val = self.bit.query(node.end + 1) - self.bit.query(node.start)
        if self.root:
            self.bit.update(node.start, node_val)
            self.bit.update(node.end + 1, -node_val)
            self.root = self._merge(self.root, node)
            self._push_node(self.root)
        else:
            self.root = node
            self.bit = BIT(20000)

