            to_merge.append([i.start, new_end])
        new_intervals.pop()
        new_intervals.extend(to_merge)
        new_intervals.sort(key=lambda x: x[0])
        return self.shift(new_intervals)

    def shift(self, intervals):
        new_intervals = []
        start, end = intervals[0]
        for i in intervals[1:]:
            if i[0] <= end:
                end = max(end, i[1])
            else:
