    for start, end in intervals:
        node = tree.root
        insert_merges = set()
        while node is not None:
            if (node.end <= start and not any(s <= node.end <= e for s, e in result_merges)) or \
               (node.end <= start and tree.query(node.right, start, end) or tree.root is None):
                break
            left_key = start - 1
            right_key = node.start
            while left_key + 1 < right_key:
                key = (left_key + right_key) // 2
                if key == start:
                    break
                if tree.query(node, key, end):
                    right_key = key
                else:
                    left_key = key
            merge = (left_key + 1, right_key)
            insert_merges.add(merge)
            node = node.left if tree.query(node, start, right_key) else node.right
        tree.root = tree.insert(tree.root, start, end)
        for merge_start, merge_end in list(insert_merges):
            node = tree.root
            found = False
            while node is not None:
                if merge_start <= node.start and merge_end >= node.end:
                    break
                if node.left is not None:
                    found_left = node.left.start <= merge_end and merge_start <= node.left.end
                    if found_left and node.left.start > node.right.start:
                        node, _ = tree._rotate_right(node)
                    node = node.left if found_left else node.right
                else:
                    node = tree._remove(node, merge_start, merge_end)
                    found = True
                    break
            if found:
                result_merges.add((merge_start, merge_end))
    final_merges = [(merge[0], merge[1]) for merge in result_merges]
    final_merges.sort(key=lambda x: x[0])
    return

