        if not self.intervals:
            self.intervals.append(interval)
        else:
            self._insert_into_tree(self.intervals, interval)

    def _insert_into_tree(self, tree, interval):
        if len(tree) > 1:
            mid = len(tree) // 2
            if interval.start < tree[mid].start:
                self._insert_into_tree(tree[:mid], interval)
            else:
                self._insert_into_tree(tree[mid:], interval)
                self.intervals = tree[:mid] + [interval] + tree[mid:]
        else:
            tree.append(interval)

    def search(self, start, end):
        result = []
        self._search_tree(self.intervals, start, end, result)
        if result:
            return [result[0]]
        return []

    def _search_tree(self, tree, start, end, result):
        for i in range(len(tree)):
            if tree[i].start < end:
                if tree[i].end >= start:
                    start = min(start, tree[i].start)
                    end = max(end, tree[i].end)
                else:
                    start = tree[i+1].start if i+1 < len(tree) else start
                    break
        if start <= end:
            result.append(Interval(start, end))

