class IntervalTree:
    def __init__(self):
        self.root = None

    def insert(self, start, end):
        self.root = self._insert(self.root, start, end)

    def _insert(self, node, start, end):
        if node is None:
            node = Node(start, end)
        if start > node.max_right:
            node.max_right = start
            node.right = self._insert(node.right, start, end)
        else:
            node.max_left = end
            node.left = self._insert(node.left, start, end)
        return node

    def merge_overlaps(self):
        intervals = []
        self._merge_overlaps(self.root, intervals)
        intervals.sort(key=lambda x: x[0])
        merged_intervals = []
        for interval in intervals:
            if not merged_intervals or interval[0] > merged_intervals[-1][1]:
                merged_intervals.append(interval)
            else:
                merged_intervals[-1][1] = max(merged_intervals[-1][1], interval[1])
        return merged_intervals

    def _merge_overlaps(self, node, intervals):
        if node is not None:
            self._merge_overlaps(node.left, intervals)
            if node.max_left <= node.max_right:
                intervals.append([node.max_left, node.max_right])
            self._merge_overlaps(node.right, intervals)

