class SlidingWindow:
    def __init__(self, a, k):
        from collections import deque
        self.deque = deque()
        self.n = len(a)
        self.k = k
        self.cache = {}

    def getMax(self):
        if (self.n, self.k) in self.cache:
            return self.cache[(self.n, self.k)]
        ans = float('-inf')
        for i in range(self.k):
            if self.deque:
                ans = max(ans, a[i])
            self.deque.append(a[i])
        left = 0
        for right in range(self.k, self.n):
            ans = max(ans, a[right])
            self.deque.append(a[right])
            if a[left] == self.deque[0]:
                self.deque.popleft()
                left += 1
            self.cache[(self.n, self.k)] = ans
        return ans

class mergesort_sliderow:
    from functools import lru_cache

    @lru_cache(None)
    def merge_sort(self, nums):
        if len(nums) <= 1:
            return nums
        mid = len(nums) // 2
        return merge(self.merge_sort(nums[:mid]), self.merge_sort(nums[mid:]))

    def merge(self, a, b):
        res = []
        i = j = 0
        while i < len(a) and j < len(b):
            if a[i] <= b[j]:
                res.append(a[i])
                i += 1
            else:
                res.append(b[j])
                j += 1
        res.extend(a[i:])
        res.extend(b[j:])
        return res

