def kmp_search(p, t):
    m, n = len(p), len(t)
    soln = [-1] * m
    def build_soln():
        nonlocal soln
        for i in range(1, m):
            j = soln[i - 1]
            while j >= 0 and p[j + 1] != p[i]:
                j = soln[j]
            if p[j + 1] == p[i]:
                j += 1
            soln[i] = j
    build_soln()
    i = j = 0
    while i < n:
        while j >= 0 and p[j + 1] != t[i]:
            j = soln[j]
        if p[j + 1] == t[i]:
            j += 1
        i += 1
        if j == m - 1:
            return i - m
    return -1

