            sorted_nums[j] += sorted_nums[j - 1] + v // M * (v // M + 1) // 2 + (v % M)
            if z == nums[j-1] // M:
                sorted_nums[j] = sorted_nums[j-1]
            elif nums[i] // M > nums[j-1] // M:
                z += 1
                updated = sorted_nums[j] - sorted_nums[j - 1]
                if updated != 0:
                    ft.update(z, updated)
                sorted_nums[j] = 0
            j += 1
    return ft.upper_bound(0) + 1

