def solve(nums):
    n = len(nums)
    compressed = sorted(nums)
    bit_size = (n + 31 - 1) // 31
    bit_mask = (1 << bit_size) - 1
    fenwick = [0] * ((n + 1) * bit_size)

    def lower_bound(num):
        'Return the insertion point of num in sorted_num'
        left, right = 0, n - 1
        while left <= right:
            mid = (left + right) // 2
            if compressed[mid + 1] < num:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def fenwick_update(index, value):
        'Increment the bit at index by value in fenwick'
        while index <= n:
            for i in range(bit_size):
                fenwick[index + i] += value
            index += index & -index

    def fenwick_query(index):
        'Return the sum of bits up to index in fenwick'
        result = 0
        while index:
            result += fenwick[index]
            index -= index & -index
        return result

    def fenwick_range_query(left, right):
        'Return the sum of bits in [left, right) in fenwick'
        return fenwick_query(right) - fenwick_query(left - 1)

    dp = [0] * (n + 1)
    dp[lower_bound(nums[0])] = 1
    for i, num in enumerate(nums):
        original_index = (num ^ (num >> 5) ^ (num >> 10) ^ (num >> 15) ^ (num >> 20) ^ (num >> 25))  & 31
        index = lower_bound(num)
        fenwick_update(original_index, 1)
        dp[index + 1] = max(dp[index + 1], dp[index] + 1)
        if i > 0:
            for j in range(bit_size):
                if fenwick[index + j] > 0:
                    dp[index + 1] = max(dp[index + 1], dp[index + j - bit_mask] + 1)

    return max(dp)

