def partition(nums, pivot_index):
    pivot = nums[pivot_index]
    left = [num for i, num in enumerate(nums) if i < pivot_index]
    right = [num for i, num in enumerate(nums) if i > pivot_index]
    left_counts = {num: counts.get(num, 0) for num, counts in [(num, counts) for num, counts in counts.items() if num <= pivot]}
    right_counts = {num: counts for num, counts in counts.items() if num > pivot}
    while len(left) + len(right) < len(nums):
        if all(counts.get(num, 0) for num in left_counts.keys() + right_counts.keys()):
            sorted_lists = sorted([(left_counts.keys() + right_counts.keys()), left],
                                  key=lambda x: x[0][0] if x else '',
                                  reverse = True)
            if left_counts[sorted_lists[0][0]] > 0 and left_counts[sorted_lists[0][0]] >= right_counts.get(sorted_lists[0][0], 0):
                left_counts[sorted_lists[0][0]] -= 1
                left.append(sorted_lists[0][0])
            else:
                right_counts[sorted_lists[0][0]] -= 1
                right.append(sorted_lists[0][0])
    left.append(pivot)
    return len(left), left, right

