class MinMaxHeap:
    def __init__(self, nums):
        self.heap = [nums[0]]
        for num in nums[1:]:
            self._heapify_up(self.heap, num)
            self._heapify_down(self.heap)

    def _heapify_up(self, heap, num):
        i = len(heap) - 1
        while i > 0:
            parent_idx = (i - 1) // 2
            if heap[parent_idx] > num:
                heap[parent_idx], heap[i] = heap[i], heap[parent_idx]
                i = parent_idx
            else:
                break

    def _heapify_down(self, heap):
        i = 0
        while i < len(heap):
            left_child_idx = 2 * i + 1
            right_child_idx = 2 * i + 2
            if left_child_idx < len(heap):
                min_child_idx = left_child_idx if heap[left_child_idx] < heap[right_child_idx] else right_child_idx
                if heap[i] > heap[min_child_idx]:
                    heap[i], heap[min_child_idx] = heap[min_child_idx], heap[i]
                    i = min_child_idx
                else:
                    break
            elif right_child_idx < len(heap):
                if heap[i] > heap[right_child_idx]:
                    heap[i], heap[right_child_idx] = heap[right_child_idx], heap[i]
                    i = right_child_idx
                else:
                    break
            else:
