    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [1]*(n+1)
        self.size = [1]*(n+1)
    def find(self, x):
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        while x != root:
