def suffix_array_maker(sa_helper, prefix_function):
    sa: list[int] = []
    first_occurrence_list: dict[str,int] = {}
    for c in prefix_function:
        if c in first_occurrence_list:
            first_occurrence_list[c].append(c)
        else:
            first_occurrence_list[c] = [c]
    for key in sorted(first_occurrence_list.keys()):
        for s in first_occurrence_list[key]:
            if (s == 0):
                sa.append(sa_helper)
                break
            else:
                i = int(s)
                index = sa[i - 1] if i > 1 else -1
                if i > 1:
                    val_index = i - 1
                    sa.append(index)
                    while val_index >= 0 and i >= val_index:
                        index = sa_helper[val_index]
                        sa[val_index] = index
                        sa[val_index-1] = -1
                        val_index-=1
                else:
                    val_index = i - 1
                    new_val_index = val_index
                    val: int = sa_helper[val_index]
                    while val_index >= 0 and new_val_index >= 0:
                        sa[val_index] = val
                        sa[val_index-1] = -1
                        new_val_index -= 1
                        val_index-=1
                    sa.append(val)
    return sa


