def solve(nums, k):
    def median_of_three(left, mid, right):
        if nums[left] < nums[mid]: 
            if nums[mid] < nums[right]: return mid
            elif nums[left] < nums[right]: return right
            else: return left
        else: 
            if nums[mid] < nums[right]: return left
            elif nums[left] < nums[right]: return right
            else: return mid

    def partition(left, right):
        pivot_index = median_of_three(left, (left + right) // 2, right)
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        i = left
        for j in range(left, right):
            if nums[j] < nums[right]:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
        nums[i], nums[right] = nums[right], nums[i]
        return i

    def quickselect(left, right, k):
        if left == right: return left
        pivot_index = partition(left, right)
        if k == pivot_index + 1: return pivot_index
        elif k < pivot_index + 1: return quickselect(left, pivot_index - 1, k)
        else: return quickselect(pivot_index + 1, right, k - (pivot_index + 1))

    return nums[quickselect(0, len(nums) - 1, k)]

