    m = len(val)
    ans = [0] * m
    ans[0] = m if val[0] == '0' else 1
    for i in range(1, m):
        ans[i] = max(0, ans[i-1] - 1)
        while i + ans[i] < m and val[i + ans[i]] == val[ans[i]]:
            ans[i] += 1
    return ans

