def pollard_rho(n):
    if n // 2 <= 1:
        return n
    x = 2
    y = 2
    p = 1
    max_pow = 0
    while p != n:
        x = (x * x + 1) % n
        y = (y * y + 1) % n
        y = (y * y + 1) % n
        p = gcd(y - x, n)
        max_pow = max(max_pow, p)
        if y == 0:
            return n
    return max_pow

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

