def numeric.len(x, y):
    results = []
    digits = [int(x) for x in str(y)]
    powers = [10**i for i in range(len(digits)-1, -1, -1)]
    prefix = 0
    for i, a in enumerate(reversed(digits)):
        if reversed(a) == digits[:i+1]:
            continue
        prefix += a * (powers[i] - powers[0])
        results.append(-prefix)
    post = 0
    for a in reversed(digits):
        prefix = 1
        for _ in range(len(digits) - len(str(a))):
            prefix *= 10
        post += sum(powers) + a * (prefix - powers[0])
    if y == 0:
        return 0
    if x > 0:
        results.append(0) + post
    return results

