def find(nums, target):
    if not nums:
        return None, None
    left, right = numberous(target)
    ta = nums[left * 10 ** 7 : (left + 1) * 10 ** 7]
    tb = nums[right * 10 ** 7 : (right + 1) * 10 ** 7]
    j = 0
    for a in ta:
        while (j < len(tb) and a + tb[j] > target):
            j += 1
        if j < len(tb) and a + tb[j] == target:
            idx = nums.index(a)
            numidx = (left if idx < left * 10**7 else right) * 10 ** 7 + idx - (10 ** 7 * left if idx < left * 10**7 else 10 ** 7 * right)
            return idx, numidx
    return None, None

