def solve(nums: List[int], target: int, min_val: int = -10**9, max_val: int = 10**9) -> list:
    if len(nums) <= 1:
        return []

    Lo, Hi = {k: v for v, k in enumerate(nums)}, dict()

    for i, num in enumerate(nums):
        Complement = target - num
        if Complement == num:
            index = bisect_left(list(Lo.keys()), num)
            if Lo[num] == list(Lo.keys())[index]:
                del Lo[num]
                if Complement in Hi:
                    return [Lo.get(Complement, -1), Hi[Complement]]
                continue
        Low_eq = (Lo.get(Complement, float('inf')) - num > 0)
        Hi_num = Lo.get(Complement, float('inf')) - Lo.get(num, float('inf'))

        if Complement in Lo:
            Lo[Complement] = min(Lo[Complement], i)
        else:
            Lo[Complement] = i

        Lo.pop(num, None)
        if Low_eq and Complement <= Hi_num:
            end = bisect_right([v for v in Lo.values()], Hi_num)
            Lo.pop(list(Lo.keys())[end], None)
            done_eq = False
            j = end-1
            while True:
                entry = list(Lo.keys())[j]
                exist_eq_num = nums[j] == nums[j+i]+target
                if exist_eq_num:
                    done_eq = True
                else:
                    Lo[nums[j]] = j
                    done_eq |= False
                if entry == Complement or done_eq:
                    if entry == Complement and exist_eq_num:
                        # skip duplicates
                        num_xml = nums[j+i]+target
                        Lo[num_xml] = Lo.pop(num_xml, float('inf')) 
                    break
                j -= 1
        Hi[target - num] = i
    return [-1, -1]

