def binary_search(arr, target, index):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid if mid < index else -mid - 1
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -low - 1 if low >= 0 else -high - 1

