def hashcash(nums, target):
    """Hash table with cashing, an efficient sparse hash table"""
    hash_size = 1000003  # prime number
    hash_table = [-1] * hash_size
    for i, num in enumerate(nums):
        j = (target - num if target > num else num - target) + hash_size  # adjust to move close to origin
        j %= hash_size
        if hash_table[j] == -1:  # empty slot
            hash_table[j] = i
        else:  # slot occupied, save previous slot
            slot_chain = [hash_table[j]]
            while hash_table[hash_table[j]] != -1:
                slot_chain.append(hash_table[hash_table[j]])
                hash_table[hash_table[j]] = -1
            for slot_idx in Slot_finder(slot_chain):
                if target == nums[i] + nums[slot_idx]:
                    return [slot_idx, i]
            # save updated slot chain in table
            hash_table[j] = i
    return []

class Slot_finder:
    """Find slots in a chain"""
    def __init__(self, slots):
        self.slots = slots
        self.index = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.index == len(self.slots):
            raise StopIteration
        idx = self.slots[self.index]
        self.index += 1
        return idx

