def _sort_and_search(nums, left, right, target):
    if left == right:
        return left
    mid = (left + right) // 2
    if nums[left] + nums[mid] <= target:
        right_thumb = mid
        left_thumb = left
    else:
        right_thumb = right
        left_thumb = mid + 1
    while left <= right:
        found = right_thumb - left + 1
        while left < left_thumb and nums[left] + nums[left_thumb] < target:
            left += 1
            found -= 1
        if found == 0:
            return left
        right_thumb -= 1
        right -= found
    return left + 1

