class HashedList:
    def __init__(self, nums):
        self.keys = {}
        self.values = {}
        for i, num in enumerate(nums):
            key = hash(num)
            self.keys[key] = i
            self.values.setdefault(i, []).append(key)
            for val in [(num + num), 2 * num, num << 1, num >> 1]:
                if val < -10**9 or val > 10**9:
                    continue
                val_key = hash(val)
                self.values.setdefault(i, []).append(val_key)
                self.keys.setdefault(val_key, float('inf'))

