def pushify(edges):
    """Return an iterator which yields the item with the highest preorder count."""
    count = 0
    seen = 0
    while seen < len(edges):
        item = edges[seen]
        if seen == 0 or item > edges[seen - 1]:
            count += 1
        push(edges, item)
        seen += 1
    return iter(make_stack())

class DisjointSet:
    """Represent a disjoint-set (union-find) data structure."""
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, i):
        """Return the representative of the set containing i."""
        if self.parent[i] != i:
            self.parent[i] = self.find(self.parent[i])
        return self.parent[i]

    def union(self, x, y):
        """Merge the sets containing x and y, if they have no common elements."""
        rootx, rooty = self.find(x), self.find(y)
        if rootx == rooty: return
        if self.rank[rootx] > self.rank[rooty]:
            self.parent[rooty] = rootx
        else:
            self.parent[rootx] = rooty
            if self.rank[rootx] == self.rank[rooty]:
                self.rank[rooty] += 1

