    """Return the number of connected components of an undirected graph."""
    order = tuple(sorted(edges))
    visit = [False] * n
    ds = DisjointSet(n)
    max preorder, seen = 0, 0
    for _, item in enumerate(pushify(list(order))):
        u, v = item
        if not visit[u]:
            for adj in adjacents(edges, u, seen):
                ds.union(u, adj)
            visit[u] = True
            seen += 1
        if not visit[v]:
            for adj in adjacents(edges, v, seen):
                ds.union(v, adj)
            visit[v] = True
            seen += 1
        c = ds.find(u)
        max preorder = max(max preorder, preorder[c])
    return max preorder + 1

