            dsu.union(u, v)
            timestamps.append(dsu.time)

    # Use this list of timestamps
    if min(timestamps) == 0:  # no edges were applied to unconnected nodes
        return 1

    clock = 0
    next_clock_time = timestamp()
    next_time = next_clock_time
    ids = [0] * n
    for u, v in edges:
        if dsu.find(u) != dsu.find(v):
