def solve(n: int, edges: List[List[int]]) -> int:
    _components = n

    def _passed(u: int, v: int) -> bool:
        for c in _components:
            if u in c and v in c:
                return True
        return False

    def _connect(u: int, v: int) -> bool:
        nonlocal _components

        u_set, v_set = set(), set()
        new = True
        changed = False
        while u_set != v_set and new:
            new = False
            for i in u_set:
                for j in _components[u_set]:
                    if _passed(j, i):
                        v_set.add(i)
                        new = True
                        changed = True
            for i in v_set:
                for j in _components[v_set]:
                    if _passed(j, i):
                        u_set.add(i)
                        new = True
                        changed = True
            if new:
                for i in v_set:
                    u_set.add(i)
                    del _components[u_set]
        if v_set != u_set and changed:
            _components[u_set + v_set]

    for u, v in edges:
        _connect(u, v)
        if not _passed(u, v):
            _share = {u, v}
            for _ in range(n):
                for i in _components[_share]:
                    for j in _components[_share]:
                        if _passed(i, j):
                            _share.add(j)
                            break
            del _components[_share - {u, v}]
            _components.append(_share - {u, v})
            _components.append({i for i in range(n) if i not in _share})

    return len(_components)

