def collect(perm):
    n = len(perm)
    edges = [(perm[i], perm[i+1]) for i in range(n-1)]
    for i in range(n-1, 3, -1):
        edges.append((perm[i-1], perm[i]))
        perm[-(i%3)-1:] = perm[-(i%3):][::-1]
    return edges

def shuffle(edges):
    n = max(max(x, y) for (x, y) in edges) + 1
    perm = list(range(n))
    for i in range(n - 2):
        for i in range(n - 2, 0, -1):
            j = random.randint(0, i - 1)
            perm[i], perm[j] = perm[j], perm[i]
    perm = collect(perm)
    return perm

