def binary_search(l: list, target: int) -> int:
    left, right = 0, len(l)
    while left < right:
        mid = (left + right) // 2
        if l[mid] >= target:
            right = mid
        else:
            left = mid + 1
    return left

def rev_binary_search(l: list, target: int):
    left, right = 0, len(l)
    while left < right:
        mid = (left + right) // 2
        if l[mid] <= target:
            left = mid + 1
        else:
            right = mid
    return left

