    low = 0
    high = len(l)-1
    guess = high

    while guess != low:
        mid = (low + high) // 2
        if l[mid] < k:
            low = mid+1
        else:
            high = mid
        if not low == high and l[low] == k: low +=1
        guess = high
    return guess

def bisect_point_in_searchsorted(lst, value) -> int:
    left, right = 0, len(lst)
    res = left
    while left <= right:
        mid = (left + right) // 2
        if lst[mid] < value:
            left = mid + 1
        else:
            right = mid
        if lst[mid] == value:
            if mid == 0 or lst[mid - 1] < value:
                res = mid
            else:
                right = mid - 1
    return res

