class SegmentTree:
    def __init__(self, n):
        self.size = 1 << (n - 1).bit_length()
        self.data = [0] * (2 * self.size)

    def build(self, x, l, r):
        if l + 1 == r:
            self.data[x] = 0
            return
        m = (l + r) // 2
        self.build(x * 2 + 1, l, m)
        self.build(x * 2 + 2, m, r)
        self.data[x] = self.data[x * 2 + 1] + self.data[x * 2 + 2]

    def update(self, x, l, r, i, value):
        if l == r - 1:
            self.data[x] = value
            return
        m = (l + r) // 2
        if i < m:
            self.update(x * 2 + 1, l, m, i, value)
        else:
            self.update(x * 2 + 2, m, r, i, value)
        self.data[x] = self.data[x * 2 + 1] + self.data[x * 2 + 2]

    def query(self, x, l, r,ql, qr):
        if l >= qr or ql >= r:
            return 0
        if ql <= l and r <= qr:
            return self.data[x]
        m = (l + r) // 2
        return self.query(x * 2 + 1, l, m, ql, qr) + self.query(x * 2 + 2, m, r, ql, qr)

