class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [-float('inf')] * (4 * n)
        self.lazy = [None] * (4 * n)

    def build(self, idx, lo, hi):
        if lo == hi:
            self.tree[idx] = self.lazy[idx] = lo
        else:
            mid = (lo + hi) // 2
            self.build(idx * 2 + 1, lo, mid)
            self.build(idx * 2 + 2, mid + 1, hi)
            self.tree[idx] = max(self.tree[idx * 2 + 1], self.tree[idx * 2 + 2])

    def push(self, idx, lo, hi):
        if lo != hi and self.lazy[idx] is not None:
            self.lazy[idx * 2 + 1] = self.lazy[idx]
            self.lazy[idx * 2 + 2] = self.lazy[idx]
            self.tree[idx * 2 + 1] = self.lazy[idx] if self.lazy[idx] <= self.n else int(2.2e9)
            self.tree[idx * 2 + 2] = self.lazy[idx] if self.lazy[idx] <= self.n else int(2.2e9)
            self.lazy[idx] = None

    def update(self, lo, hi, val, idx, lo_range, hi_range):
        self.push(idx, lo_range, hi_range)
        if lo > hi or lo > hi_range or hi < lo_range:
            return
        if lo >= lo_range and hi <= hi_range:
            self.lazy[idx] = val
            self.tree[idx] = val if val <= self.n else int(2.2e9)
        else:
            mid = (lo_range + hi_range) // 2
            self.update(lo, hi, val, idx * 2 + 1, lo_range, mid)
            self.update(lo, hi, val, idx * 2 + 2, mid + 1, hi_range)
            self.tree[idx] = max(self.tree[idx * 2 + 1], self.tree[idx * 2 + 2])

    def query(self, idx, lo, hi, lo_range, hi_range):
        self.push(idx, lo, hi)
        if lo > hi or lo > hi_range or hi < lo_range:
            return -float('inf')
        if lo >= lo_range and hi <= hi_range:
            return self.tree[idx]
        mid = (lo_range + hi_range) // 2
        return max(self.query(idx * 2 + 1, lo, hi, lo_range, mid), self.query(idx * 2 + 2, lo, hi, mid + 1, hi_range))

