    while len(pq) >= 2 and pq[0][1] < end and pq[1][1] < end:
        first_start, first_end = heapq.heappop(pq)
        second_start, second_end = heapq.heappop(pq)
        start = min(first_start, second_start)
        end = max(first_end, second_end)
        return start, end
    return None, None

