def merge_sort_intervals(intervals):
    if not intervals:
        return []

    intervals.sort(key=lambda x: x[0])
    result = [intervals[0]]

    for i in range(1, len(intervals)):
        if intervals[i][0] > result[-1][1]:
            result.append(intervals[i])
        else:
            result[-1][1] = max(result[-1][1], intervals[i][1])

    return result

def solve(intervals):
    size = len(intervals)
    intervals_of_overlap = []

    i = 0
    j = 1
    prev_merged = -1
    end_merged = -1

    while i < size:
        if j == i + 1:
            j += 1
            i += 1
        else:
            if i == prev_merged + 1:
                end_merged = max([end_merged, intervals[i][1]])
                i += 1
                if i == j and end_merged <= intervals[j][0]:
                    end_merged = -1
                    j = i + 1
                else:
                    j = i
            else:
                prev_merged = i
                intervals_of_overlap.append((intervals[i][0], intervals[i][1]))
                i = j
                j = i + 1

    result = merge_sort_intervals(intervals_of_overlap)
    return len(intervals) - len(result)

