class Matrix:
    def __init__(self, A=None, B=None, C=None, D=None):
        self.A, self.B, self.C, self.D = A, B, C, D

    def times(self, other):
        if self.D is None or other.A is None:
            raise ValueError('matrices are not compatible')
        return Matrix(
            self.A * other.A + self.B * other.C,
            self.A * other.B + self.B * other.D,
            self.C * other.A + self.D * other.C,
            self.C * other.B + self.D * other.D
        )

def multiply(matrix, number):
    if matrix is None:
        return None
    assert matrix.D is None
    return Matrix(
        matrix.A * number,
        matrix.B * number,
        matrix.C * number,
        matrix.D * number
    )

def power(matrix, k):
    small = None
    big = matrix
    while k:
        if k % 2 == 1:
            small = multiply(small, big)
        k //= 2
        big = multiply(big, big)
    return small

