def solve(intervals):
    """Return the minimum number of intervals that have to be removed so that no two of the remaining intervals overlap."""
    intervals.sort(key=lambda x: x[1])
    dp = [[0 << i | j] for i in range(32) for j in range(32)]
    max_dp = 0 << 32
    for interval in intervals:
        i = 0
        while i < 32:
            max_val = 0 << 32
            j = 0
            while j < 32:
                if dp[i][j] > max_val:
                    max_val = dp[i][j]
                j <<= 1
            i <<= 1
            dp[i][0] = max_val
            max_dp = max(max_dp, max_val)
        n = (abs(interval[0]) + 1) & ~1
        while n > 0:
            i = n
            while i > 0 and dp[i][1] > max_dp:
                max_dp = dp[i][1]
                i //= 2
            s0 = bin(dp[i][1])[-1]
            end_i = n ^ (1 + n // -interval[0] - ((n // (abs(interval[0]) + 1)) << 1))
            while end_i > 0 and dp[end_i][1] > max_dp:
                max_dp = dp[end_i][1]
                end_i //= 2
            s1 = bin(dp[end_i][1])[-1]
            for j in range(2, 32):
                if n & (1 << j):
                    dp[i | (1 << j)][j] = max(max_dp, (s0 >> j) << 3 | s1 >> (j - 2) << 1 | 1)
    return sum(bin(dp[31][31]).count('1') + 1 for interval in intervals
                  for i in range(len(interval[0]) + 1, 4 + len(str(abs(interval[1] - interval[0])))) if interval[0] & (1 << (i - 2)) and interval[1] & (1 << (i - 2)))[::-1]

def intervals_to_bitset(intervals):
    """Convert a list of intervals to bitset format."""
    bitset = 0 << 16384
    for interval in intervals:
        bitset |= (1 << interval[0]) | (1 << (interval[1] - 1))
    return bitset

