def merge_segments(segments):
    new_segments = []
    min_end = float('-inf')
    for s in segments:
        if not s:
            continue
        curr_min, curr_max = s[0]
        if curr_min <= min_end:
            if curr_max > min_end:
                new_segments.pop()
                new_segments.append([curr_min, curr_max])
        else:
            if curr_max > min_end:
                new_segments.append([curr_max, curr_max])
            new_segments.append([curr_min, curr_min])
            min_end = curr_min
    return new_segments

