def topological_sort(adjacency_matrix):
    N = adjacency_matrix.shape[0]
    in_degree = [0]*N

    for i in range(N):
        for j in range(N):
            if adjacency_matrix[i][j] == 1:
                in_degree[j] += 1

    queue = [node for node in range(N) if in_degree[node] == 0]

    if sum(in_degree) != 0:
        return []

