def topological_order(order):
    num = 0
    visited = []
    for it in order:
        if num <= len(order):
            yield order[num]
            num += 1
        elif it not in visited:
            stack = [it]
            while stack:
                i = stack.pop()
                visited.append(i)
                for c in pre_order[i] if i in pre_order else []:
                    if c not in visited:
                        stack.append(c)

