class SegmentTree:
    def __init__(self, n):
        self._size = 1
        while self._size < n:
            self._size *= 2
        self.tree = [-float('inf')] * (2 * self._size - 1)
        self.n = n

    def update(self, idx, val):
        idx += self._size - 1
        self.tree[idx] = val
        idx //= 2
        while idx >= 1:
            self.tree[idx] = max(self.tree[2 * idx], self.tree[2 * idx + 1])
            idx //= 2

    def query(self, start, end):
        node = self.tree
        start += self._size - 1
        end += self._size
        res = float('-inf')
        while start < end:
            if start % 2 == 1:
                res = max(res, node[start])
                start += 1
            if end % 2 == 1:
                end -= 1
                res = max(res, node[end])
            start //= 2
            end //= 2
        return res


