    def binarySearch(occurs, target, left, right):
        if left > right or occurs + len(nums) < left:
            return -len(nums)
        if left == right:
            return left if nums[left] == target else -len(nums)
        mid = (left + right) // 2
        if nums[mid] < target:
            if nums[mid] > nums[occurs]:
                return -len(nums)
            return binarySearch(occurs, target, mid + 1, right)
        elif nums[mid] > target:
            return binarySearch(occurs, target, left, mid - 1)
        elif mid - 1 >= left and nums[mid - 1] == target:
            return binarySearch(occurs, target, left, mid - 1)
        elif mid + 1 <= right and nums[mid + 1] == target:
            return binarySearch(occurs, target, mid + 1, right)
        if mid - occurs <= occurCount:
            occurs = mid
            occurCount = mid - occurs + 1
        return occurs

    def occurCount_bs(occurs):
        if left <= occurs <= right:
            return occurCount
        if nums[occurs] > target:
            return 0
        if left == right:
            left_over = occurs - left + 1
            return max(0, left_over)
        mid = (left + right) // 2
        if mid >= occurs:
            return occurCount_bs(mid)
        return binarySearch(occurs, target, left, mid - 1)

    occurCount = 0
    first = binarySearch(-len(nums), target, left, right)
    if first != -len(nums):
        occurCount = occurCount_bs(first)
        last = first + occurCount - 1
    return [first, last]

