MOD = 2**63 - 1

def solve(nums, target):
    def bisect_left(nums, target):
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) >> 1
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    def bisect_right(nums, target):
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) >> 1
            if target <= nums[mid]:
                right = mid
            else:
                left = mid + 1
        return left

    def search_first_last(nums, targets, last_seen):
        result = []
        for target in targets:
            if target < nums[0] or last_seen[target] == MOD:
                result.append(-1)
            else:
                idx =bisect_right(nums, target)
                if idx == 0 or nums[idx - 1] != target:
                    result.append(-1)
                else:   
                    result.append(last_seen[target])
        return result

    def lazy_segment_tree(nums):
        n = len(nums)
        tree = [-1] * (4 * n)
        pressured_nodes = deque()
        last_seen = [-1] * 10**9

        def build(idx, left, right):
            if right - left == 1:
                tree[idx] = left
                last_seen[nums[left]] = idx
                return
            mid = (left + right) >> 1
            left_child = 2 * idx + 1
            right_child = 2 * idx + 2
            build(left_child, left, mid)
            build(right_child, mid, right)
            if tree[left_child] != -1 and nums[tree[left_child]] == nums[mid]:
                pressured_nodes.append((idx // 2, tree[left_child]))
                tree[idx] = tree[left_child]
                last_seen[nums[mid]] = idx
            else:
                tree[idx] = tree[right_child]

        def process(node, left, right):
            if node == left:
                tree[node] = left
                return
            mid = (left + right) >> 1
            if pressured_nodes and pressured_nodes[0][0] == node:
                pressured_node = pressured_nodes.popleft()
                assert tree[2*node + 2] == -1
                tree[node] = tree[2*node + 1]
                last_seen[nums[tree[node]]] = node
                if pressured_node[1] != -1:
                    pressured_nodes.appendleft((2*node + 1, pressured_node[1]))
            build(node, left, right)
            process(2*node + 1, left, mid)
            process(2*node + 2, mid, right)

        build(0, 0, n)
        process(0, 0, n)
        targets = set()
        for i in range(n):
            if nums[i] == target:
                targets.add(nums[i])
        return search_first_last(nums, targets, last_seen)

    return lazy_segment_tree(nums)

