def _heapq_nsmallest(k, lst, key=lambda x: x, reverse=False):
    if len(lst) < k:
        return _heapq_nsmallest(k, sorted(lst, key=key, reverse=reverse)[:len(lst)], key, reverse)
    if len(lst) == 1:
        return lst if reverse else []
    mid = len(lst) // 2
    left = _heapq_nsmallest(k, lst[:mid], key, reverse)
