def topK (items, k):
    n = len(items)
    bucket_size = max(1, n // (k * 2))
    count = [0] * n
    buckets = [[] for _ in range(n // bucket_size + 1)]

    for i, value in enumerate(items):
        index = value // bucket_size
        buckets[index].append(i)

    for bucket in buckets:
        bucket.sort(key=lambda x:-items[x])
        for i in range(0, len(bucket), bucket_size):
            for j in range(i, min(i + bucket_size, len(bucket))):
                count[bucket[j]] = j // bucket_size + 1

    return count

