from typing import Optional, List

class Node:
    def __init__(self, x: int):
        self.val = x
        self.left = None
        self.right = None

class AvlTree:
    def __init__(self):
        self.root = None

    def insert(self, root: Optional[Node], x: int) -> Node:
        if not root:
            return Node(x)
        if x < root.val:
            root.left = self.insert(root.left, x)
        else:
            root.right = self.insert(root.right, x)
        self.update(root)
        return root

    def update(self, root: Node) -> None:
        root.height = 1 + max(
            self.getHeight(root.left) if root.left else 0,
            self.getHeight(root.right) if root.right else 0
        )
        balance = self.getBalance(root)
        if balance > 1 and self.getBalance(root.left) >= 0:
            return self.rightRotate(root)
        if balance < -1 and self.getBalance(root.right) <= 0:
            return self.leftRotate(root)
        if balance > 1 and self.getBalance(root.left) < 0:
            root.left = self.leftRotate(root.left)
            return self.rightRotate(root)
        if balance < -1 and self.getBalance(root.right) > 0:
            root.right = self.rightRotate(root.right)
            return self.leftRotate(root)

    def leftRotate(self, z: Node) -> Node:
        y = z.right
        T2 = y.left
        y.left = z
        z.right = T2
        z.height = 1 + max(
            self.getHeight(z.left) if z.left else 0,
            self.getHeight(z.right) if z.right else 0
        )
        y.height = 1 + max(
            self.getHeight(y.left) if y.left else 0,
            self.getHeight(y.right) if y.right else 0
        )
        return y

    def rightRotate(self, z: Node) -> Node:
        y = z.left
        T3 = y.right
        y.right = z
        z.left = T3
        z.height = 1 + max(
            self.getHeight(z.left) if z.left else 0,
            self.getHeight(z.right) if z.right else 0
        )
        y.height = 1 + max(
            self.getHeight(y.left) if y.left else 0,
            self.getHeight(y.right) if y.right else 0
        )
        return y

    def getHeight(self, root: Node) -> int:
        if not root:
            return 0
        return root.height

    def getBalance(self, root: Node) -> int:
        if not root:
            return 0
        return self.getHeight(root.left) - self.getHeight(root.right)

def solve(nums: List[int], k: int) -> List[int]:
    from collections import Counter
    freqs = Counter(nums)
    avl = AvlTree()
    max_freq = max(freqs.values())
    for val, freq in freqs.items():
        if freq == max_freq:
            avl.insert(avl.root, val)
    rank = [0]*avl.getHeight(avl.root)
    def getRank(root: Optional[Node], r: List[int]) -> None:
        if not root:
            return
        getRank(root.left, r)
        r[1] += 1
        if r[1] == k:
            r[0] = root.val
        getRank(root.right, r)
    getRank(avl.root, rank)
    return rank[0:1]

