def heapify(diffs):
    if not diffs:
        return
    m = len(diffs)
    for i in range(m // 2, 0, -1):
        heapifyHelper(diffs, i, m)

def heapifyHelper(diffs, i, m):
    largest = i
    left = 2 * i
    right = 2 * i + 1
    if left <= m and diffs[left - 1][0] > diffs[largest - 1][0]:
        largest = left
    if right <= m and diffs[right - 1][0] > diffs[largest - 1][0]:
        largest = right
    if largest != i:
        diffs[i - 1], diffs[largest - 1] = diffs[largest - 1], diffs[i - 1]
        heapifyHelper(diffs, largest, m)

