    def find_first(nums, target, left, right):
        if left == right:
            return left if nums[left] == target else -1
        mid = (left + right) // 2
        if target <= nums[mid]:
            return find_first(nums, target, left, mid)
        return find_first(nums, target, mid + 1, right)

    def find_last(nums, target, left, right):
        if left == right:
            return left if nums[left] == target else -1
        mid = (left + right) // 2
        if target >= nums[mid]:
            return find_last(nums, target, mid, right)
        return find_last(nums, target, left, mid - 1)

