    group = defaultdict(list)
    for num in nums:
        group[num].append(num)
    uf = UnionFind(n)
    for num in nums:
        root, count = uf.find(num), uf.count[uf.find(num)] + 1
        uf.count[root] = count
        for neighbor in group[num]:
            neighbor_root = uf.find(neighbor)
            if neighbor_root != root:
                uf.union(num, neighbor)
    count = [uf.count[uf.find(num)] for num in range(n)]
    freq = Counter(count).most_common()
    target_freq = freq[-k][0]
    return [root for root in range(n) if uf.count[uf.find(root)] == target_freq]

