class counter_with_rank:
    def __init__(self, iterable):
        self.c = Counter(iterable)
        self.it = iter(sorted(self.c.values(), reverse=True))
        self.next_value = next(self.it, None)
        self.count = 0

    def __iter__(self):
        return self

    def __next__(self):
        while True:
            value = next(self.it, None)
            if value is None:
                raise StopIteration
            if value == self.next_value:
                self.count += 1
            else:
                self.next_value = value
                self.count = 1
            yield (value, self.count)

