class UnionFind:
    def __init__(self, n):
        self.id = list(range(n))
        self.count = [1] * n

    def union(self, a, b):
        x = self.leader(a)
        y = self.leader(b)
        if x == y:
            return
        if self.count[x] < self.count[y]:
            self.id[x] = y
            self.count[y] += self.count[x]
        else:
            self.id[y] = x
            self.count[x] += self.count[y]

    def leader(self, x):
        if self.id[x] == x:
            return x
        self.id[x] = self.leader(self.id[x])
        return self.id[x]

    def connected(self, a, b):
        return self.leader(a) == self.leader(b)

class BucketSort:
    def __init__(self, n):
        for i in range(n):
            os.mkdir(f'bucket_{i}')

    def sort(self, arr):
        buckets = {}
        for i in range(len(arr)):
            idx = (arr[i] - -10000) * 100 // (-10000)
            if idx not in buckets:
                buckets[idx] = []
            buckets[idx].append(arr[i])
        self._sort_helper(buckets, cnt=0)

    def _sort_helper(self, buckets, cnt):
        for k, v in buckets.items():
            with io.open(f'bucket_{k}', 'a', encoding='utf-8') as fs:
                for i in v:
                    fs.write(str(i)+'\n')
                fs.close()
            self._sort_helper(self._load(k), cnt + len(v))

    def _load(self, num_bucket, cnt=0):
        res = []
        with io.open(f'bucket_{num_bucket}', 'r', encoding='utf-8') as fs:
            lines = fs.readlines()
            for i in range(cnt, cnt+len(lines)):
                try:
                    res.append(int(lines[i][:-1]))
                except:
                    pass
        os.remove(f'bucket_{num_bucket}')
        return res


