class NLargest:
   def __init__(self, nums, k):
      self.m = m
      self.nums = nums
      self.res = []
      self.not_added = set(nums)
      self.join = defaultdict(list)
      self.count = defaultdict(int)
      self.bias = 0

      for i in range(len(nums)):
         if self.count[nums[i]] < k:
            self.count[nums[i]] += 1
            self.join[nums[i]].append(i)

      while self.not_added:
         top = ((sorted(self.join.keys(), key=lambda x: - self.join[x][-1] + self.bias)) + 
                [i for i in self.join if self.join[i] == []])[0]
         x = self.join[top].pop()
         if x == len(nums) - 1 and len(self.join[top]) == 0:
            self.bias -= 1

         if self.count[top] != k:
            if x > 0 and self.count[nums[x-1]] < k:
               self.count[nums[x-1]] += 1
               self.join[nums[x-1]].append(x-1)

            if x < m-1 and self.count[nums[x+1]] < k:
               self.count[nums[x+1]] += 1
               self.join[nums[x+1]].append(x+1)

         i = self.join.keys().index(top)
         if i > 0:
            self.res[-1].insert(0, top)
            self.not_added.remove(top)
            self.join[top] = []
            self.count[top] = 0

         if i < len(self.join):
            self.res.append([top])

   def nlargest(self):
      return self.res

   def __getitem__(self, indices):
      if indices < 0 and abs(indices) > len(self):
         raise IndexError

      if indices >= 0 and indices >= len(self):
         raise IndexError
      result = []
      for index in indices:
         result.append(self.nums[index])
      return result

   def __len__(self):
