class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (n + 1)

    def lowbit(self, i):
        return i & -i

    def add(self, i, x):
        while i <= self.n:
            self.t[i] = max(self.t[i], x)
            i += self.lowbit(i)

    def query(self, i):
        res = 0
        while i > 0:
            res = max(res, self.t[i])
            i -= self.lowbit(i)
        return res

def get_mode(nums):
    freq = {}
    for n in nums:
        freq[n] = freq.get(n, 0) + 1
    sorted_nums = sorted(freq, key=freq.__getitem__)
    count = {}
    for n in sorted_nums:
        cnt = freq[n]
        count[cnt] = count.get(cnt, 0) + 1
    heap = []
    for c in sorted(count, reverse=True):
        heapq.heappush(heap, (c, c * len(nums) - sum(i * (i-1) // 2 for i in range(1, c+1)), False))
        if len(heap) > 1 and heap[0][0] != heap[1][0]:
            break
    rt = FenwickTree(len(sorted_nums) + 1)
    for i, n in enumerate(sorted_nums):
        rt.add(i+1, n)
    ans = []
    while heap:
        c, H, flag = heapq.heappop(heap)
        if not flag:
            idx = rt.query(c) + 1
            for _ in range(c):
                rt.add(idx, sorted_nums[-1])
            if H == sum(freq[n] * rt.query(freq[n]) for n in sorted_nums if freq[n] >= c):
                ans.extend(sorted_nums[:idx])
                break
        heapq.heappush(heap, (c, H, True))
    mode = freq[sorted_nums[-k]]
    return next(n for n in sorted_nums if freq[n] == mode)

