class BucketSort:
    def __init__(self):
        self.max_freq = 0
        self.head = None
        self.tail = None

    def add_node(self, val, freq):
        node = self.locator[val]
        node.freq = freq
        if not self.head:
            self.head = node
            self.tail = node
        else:
            if freq - self.max_freq >= len(self.buckets):
                raise ValueError("Too many frequent values")
            bucket = self.buckets[freq - self.max_freq]
            if node.prev:
                node.prev.next = node.next
                if node.next:
                    node.next.prev = node.prev
            if node.next:
                node.next.prev = node.prev
                node.prev = node.next
            bucket.append(node)
            self.locator[val].next = bucket[-1]
            self.locator[val].prev = bucket[-1]
            return
            self.buckets[freq - self.max_freq].append(node)
            node.next = bucket[-1]
            if bucket[-1]:
                bucket[-1].prev = node
            if not node.prev:
