            for j in range(1, i):
                row.append(table[i - 1][j - 1] + table[i - 1][j])
            row.append(1)
            table.append(row)
        return table

    # Function to update the binomial coefficient table after appending a value
    def update_binom_table(table, num):
        n = len(table)
        new_row = [(table[n - 1][i] + num) if i > 0 else num for i in range(n)]
        return table + [new_row]

