def sweep(edges, n):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    used = [0] * n
    order = []

    for i in range(n):
        if used[i] == 0:
            dfs(i, order, graph, used)
    order.reverse()

    labels = list(range(n))
    ct = 0

    for i in range(n):
        for j in graph[i]:
            if labels[i] > labels[j]:
                labels[i] = min(labels[i], labels[j])
        if labels[i] != i:
            ct += 1

    return ct

