def compute_z_array(string):
    n = len(string)
    z = [0] * n
    left, right = 0, 0
    for i in range(1, n):
        if i > right:
            left, right = i, max(0, min(right, i - max(left, right) + 1))
            while i + z[i - left] < n and string[z[i - left]:i + z[i - left] + 1] == string[i + z[i - left]:i + z[i - left] + left + 1]:
                z[i] = z[i - left] + 1
                left = i
            else:
                right = i + z[i] - 1
        else:
            j = z[i - left]
            if z[j] < right - i + 1:
                z[i] = z[j]
            else:
                left = i
                while i + j < n and string[z[j]:i + j + 1] == string[i + j:1 + min(right, i + j - max(left, right) + 1)]:
                    z[i] = j + 1
                    left = i
                    i += 1
                right = min(right, i - 1)
                if i > right:
                    left, right = i, max(0, min(right, i - max(left, right) + 1))
                    while i + z[i - left] < n and string[z[i - left]:i + z[i - left] + 1] == string[i + z[i - left]:i + z[i - left] + left + 1]:
                        z[i] = z[i - left] + 1
                        left = i
                    else:
                        right = i + z[i] - 1
    return z

