    for start, end in intervals:
        ends.append((end, -1))
        starts.append((start, len(intervals)))
    ends.sort()
    starts.sort()

    i = 1
    for end, idx in ends:
        while i < len(starts) and starts[i][0] < end:
            dag[end, idx].append(starts[i][0], starts[i][1])
            i += 1
    i = 1
    for start, idx in starts:
        while i < len(ends) and ends[i][0] > start:
            dag[start, idx].append(ends[i][0], -i)
            i += 1

    # DP over the DAG
    cache = {}

    def dp(u, used=set()):
        if u in cache:
            return cache[u]
        intervals = 0
        for v, other in enumerate(dag[tuple(u)]):
            if v not in used:
                x, y = dp((v,), used | {v})
                if x:
                    intervals = max(intervals, y-x+1)
                else:
                    intervals += 1
        return (u[0], intervals), cache

    ans = 0
    stack = []

    def dfs(u, used=set()):
        nonlocal ans
        intervals = 0
        for v, other in enumerate(dag[tuple(u)]):
            if v not in used:
                x, y = dfs((v,), used | {v})
                if x:
                    intervals = max(intervals, y-x+1)
                else:
                    intervals += 1
        ans = max(ans, intervals)
        return (u[0], intervals)

    for u0 in range(1, len(intervals)+1):
        used = set()
        for j, (start, end) in enumerate(intervals):
            if start <= ends[j][0] <= end:
                used.add(j)
        for j, (start, end) in enumerate(intervals):
            if j not in used and starts[j][0] == ends[j][0]:
                dfs((j,))
                cache[tuple(u0)] = max(cache.get(tuple(u0), 0), ans)
                ans = 0

    return len(intervals) - max(cache.values())

