    def _dfs(self, node, color, colors, p_colors, post_order, res):
        colors[node] = color

        for neighbor in self.adj_list[node]:
            if colors[neighbor] == color and neighbor in p_colors:
                return [False, []]
            if colors[neighbor] == 0:
                p_colors.add(neighbor)
                ret, res = self._dfs(neighbor, color ^ 1, colors, p_colors, post_order, res)
                if not ret:
                    p_colors.pop()
                    return [False, []]
            elif colors[neighbor] == color:
                return [False, []]

        post_order.append(node)
        return [True, post_order]

    def _reverse_dfs(self, node, parent, colors):
        for neighbor in self.adj_list[node]:
            if neighbor != parent and colors[neighbor] == colors[node]:
                return [False]
            if colors[neighbor] == 0:
                colors[neighbor] = -colors[node]
                ret = self._reverse_dfs(neighbor, node, colors)
                if not ret:
                    return [False]
        return [True]

