class Tree:
    def __init__(self):
        self.root = Node(None)

    def insert(self, interval):
        node = self.root
        for start in range(interval[0], interval[1] + 1):
            if start not in node.children:
                node.children[start] = Node(start)
            node = node.children[start]
            node.max_end = max(node.max_end, interval[1])
        return node

    def query(self):
        intervals = []
        self._query(self.root, intervals, True)
        return [(start, end) for start, end in intervals if start != end]

    def _query(self, node, intervals, is_root):
        if node.start is not None:
            if is_root:
                intervals.append((node.start, node.max_end))
            elif intervals and intervals[-1][1] >= node.start:
                intervals[-1] = (intervals[-1][0], max(intervals[-1][1], node.max_end))
            else:
                intervals.append((node.start, node.max_end))
        if node.children:
            max_end = self.max_end_key(intervals, is_root)
            nodes_to_query = [node for node in node.children.values() if node.max_end > max_end]
            if nodes_to_query:
                node.max_end = max_end
                for child in nodes_to_query:
                    child.max_end = max_end
                self._query(node, intervals, False)
            else:
                self._query(node.children[node.max_end], intervals, False)

    @staticmethod
    def max_end_key(intervals, is_root):
        if is_root or not intervals:
            return 0
        return max(intervals[-1][1], next(key for key, value in sorted(intervals, key=lambda x: (x[0], x[1]))[-1].items())) if not all(end == start for start, end in intervals) else intervals[-1][1]

