            else:
                result[-1][1] = max(result[-1][1], end)
        return result

    def _inorder_traversal(self, node, intervals):
        if node is not None:
            self._inorder_traversal(node.left, intervals)
            intervals.append([node.start, node.end])
            self._inorder_traversal(node.right, intervals)

