from collections import defaultdict, deque

def solve(n, prerequisites):
    graph = defaultdict(list)
    indeg = [0] * n
    for parent, child in prerequisites:
        graph[parent].append(child)
        indeg[child] += 1
    reserved_cores = set()

    def hasNoChildren(c):
        return not graph[c] or len(reserved_cores & set(graph[c])) != 0

    k = None
    while True:
        has_no_children = all(hasNoChildren(j) for j in range(n))
        if has_no_children:
            for j in range(n):
                if hasNoChildren(j):
                    reserved_cores.add(j)
        else:
            for i in reversed(range(n)):
                if not hasNoChildren(i):
                    k = i
                    break
            if k is None:
                return []
            for j in graph[k]:
                indeg[j] -= 1
                if indeg[j] == 0:
                    reserved_cores.add(j)
        if k is not None:
            reserved_cores.add(k)
            k = None

    return list(reserved_cores)

class SegmentTree:
    def __init__(self, m):
        self.N = 1
        while self.N < m:
            self.N <<= 1
        self.m = m
        self.tree = [{'start': float('inf'), 'end': float('-inf')} for _ in range(2 * self.N)]
        self.stat = [0] * (2 * self.N)

    def prop(self, index, left, right):
        if self.tree[2 * index]['end'] != float('-inf'):
            self.stat[2 * index] += 1
            self.stat[2 * index + 1] += 1
            mid = (left + right) // 2
            self.tree[2 * index]['start'] = min(self.tree[2 * index]['start'], self.tree[2 * index]['end'])
            self.tree[2 * index]['end'] = float('-inf')
            self.tree[2 * index + 1]['start'] = min(self.tree[2 * index + 1]['start'], self.tree[2 * index]['end'])
            self.tree[2 * index + 1]['end'] = float('-inf')
            self.tree[2 * index] = {'start': self.tree[2 * index]['start'], 'end': self.tree[2 * index]['start']}
            self.tree[2 * index + 1] = {'start': self.tree[2 * index + 1]['start'], 'end': self.tree[2 * index + 1]['start']}

    def merge(self, begin, end, index, left, right, gap):
        if end <= left or right <= begin or self.stat[index] > 0:
            return
        if end <= right and left <= begin:
            self.tree[index]['end'] = min(self.tree[index]['end'], right - 1)
            self.tree[index]['start'] = max(self.tree[index]['start'], left - gap)
            return
        mid = (left + right) // 2
        self.prop(index, left, right)
        self.merge(begin, end, 2 * index, left, mid, gap)
        self.merge(begin, end, 2 * index + 1, mid, right, gap)
        self.tree[index]['start'] = min(self.tree[2 * index]['start'], self.tree[2 * index + 1]['start'])
        self.tree[index]['end'] = max(self.tree[2 * index]['end'], self.tree[2 * index + 1]['end'])

    def query(self, left, right):
        if left > right:
            return []
        return self._query(1, 0, self.N, left, right)

    def _query(self, index, left, right, begin, end):
        if end <= left or right <= begin:
            return [{'start': self.tree[index]['start'], 'end': self.tree[index]['end']}]
        if begin <= left and right <= end:
            ans = []
            while self.stat[index] > 0:
                gap = min(self.tree[index]['end'] - self.tree[index]['start'] + 1, self.m - 1)
                ans.append({'start': self.tree[index]['start'], 'end': self.tree[index]['start'] + gap - 1})
                self.tree[index]['start'] += gap
                self.stat[index] -= 1
            return [self.tree[index]]
        mid = (left + right) // 2
        self.prop(index, left, right)
        return self._query(2 * index, left, mid, begin, end) + self._query(2 * index + 1, mid, right, begin, end)


