class DSU:
    def __init__(self, n):
        self.root = [i for i in range(n)]
        self.rank = [0] * n
        self.size = n

    def find(self, x):
        vr = x
        while vr != self.root[vr]:
            vr = self.root[vr]
        while x != vr:
            self.root[x], x = vr, self.root[x]
        return vr

    def union(self, x, y):
        xr = self.find(x)
        yr = self.find(y)
        if xr == yr:
            return
        if self.rank[xr] < self.rank[yr]:
            self.root[xr] = yr
            self.size -= 1
        elif self.rank[yr] < self.rank[xr]:
            self.root[yr] = xr
            self.size -= 1
        else:
            self.root[yr] = xr
            self.rank[xr] += 1
            self.size -= 1

