class SegmentTree:
    def __init__(self, intervals):
        self.t = []
        for start, end in intervals:
            self._insert(start, end)
        self._sort_tree()
        self._merge_nodes()

    def _sort(self, x):
        return x[0]

    def _insert(self, start, end):
        self.t.append((start, end))
        i = len(self.t) - 1
        while i > 0:
            parent = (i - 1) // 2
            if self.t[parent][0] <= start:
                break
            self.t[i] = self.t[parent]
            i = parent

    def _sort_tree(self):
        i = 0
        while i < len(self.t):
            j = 2*i + 1
            while j < len(self.t):
                if j + 1 < len(self.t) and self._sort(self.t[j+1]) < self._sort(self.t[j]):
                    j += 1
                if self._sort(self.t[j]) < self._sort(self.t[i]):
                    self.t[i], self.t[j] = self.t[j], self.t[i]
                    i = j
                    break
                else:
                    j = 2*j + 1
            if j == 2*i + 1:
                break
            i += 1

    def _merge_nodes(self):
        while len(self.t) > 1:
            if len(self.t) % 2 != 0:
                self._merge_subtree(2*len(self.t)-2)
            self._merge_subtree(len(self.t)//2-1)
            self._sort_tree()

    def _merge_subtree(self, root):
        if root*2 + 2 >= len(self.t):
            return
        self.t[root] = self._merge_pair(self.t[root*2], self.t[root*2+1])
        left = root*2 + 2
        while 2*left + 2 < len(self.t):
            left = self._min_child(left)
            self.t[root] = self._merge_pair(self.t[root], self.t[left])
            root = left

    def _min_child(self, root):
        left, right = 2*root + 1, 2*root + 2
        return left if self._sort(self.t[left]) < self._sort(self.t[right]) else right

    def _merge_pair(self, p1, p2):
        start = min(p1[0], p2[0])
        end = max(p1[1], p2[1])
        if end < p1[1] or start > p2[0]:
            return p1 if p1[1] >= p2[1] else p2
        return [start, end]

    def query(self):
        return [subint for subint in self.t if subint[1] != self.t[0][1]]


