def most_common(nums, k):
    freqs, counts = Counter(nums), []
    for window in windows_view(nums):
        window_freqs = Counter(window).most_common()
        while window_freqs and k > 0:
            k -= 1
            freqs[window_freqs[-1][0]] += window_freqs.pop()[1]
        counts.append(max(freqs.values()))
    max_freq, idx = float('-inf'), -1
    for i, count in enumerate(counts[:-1]):
        if count > max_freq:
            max_freq, idx = count, i
    return [freq for freq, _ in freqs.most_commonuntil(max_freq, idx)]

