def solve_dfs(nums):
    @cache
    def dfs(i, prev):
        if i == len(nums):
            return 0
        if len(nums) - i < dfs.cache_cache and dfs.cache[prev] == dfs.cache_cache:
            return -1
        if prev == -1:
            return max(dfs(i + 1, j) for j in range(len(nums)))
        return 1 + max(dfs(i + 1, prev) if nums[i + 1] > nums[i] else dfs(i + 1, prev), dfs(i + 1, j) for j in range(i) if nums[i] > nums[j])

    tails = [float('inf')] * (len(nums) + 1)
    for i,n in enumerate(nums):
        idx = bisect_left(tails, n)
        tails[idx] = n
    dfs.cache_cache = idx
    dfs.cache = [0] * (idx + 1)
    return dfs.cache[0]

