def bisect_left(a, x, lo=0, hi=None):
    """Return the index `i` such that `a[i] <= x <= a[i+1]` or `i == len(a)` :elem:`-1`.
    """
    if lo < 0:
        raise ValueError('lo must be non-negative')
    if hi is None:
        hi = len(a)
    while lo < hi:
        mid = (lo + hi) >> 1
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def bisect_right(a, x, lo=0, hi=None):
    """Return the index `i` such that `a[i-1] <= x` and `a[i] > x`,
    or `i == len(a)` when `x` is great than all used elements of `a`.
    """
    if lo < 0:
        raise ValueError('lo must be non-negative')
    if hi is None:
        hi = len(a)
    while lo < hi:
        mid = (lo + hi) >> 1
        if x <= a[mid]:
            hi = mid
        else:
            lo = mid + 1
    return lo

