class SegTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)

    def pushup(self, i):
        self.tree[i] = max(self.tree[2 * i], self.tree[2 * i + 1])

    def build(self, i, l, r):
        if l == r:
            self.tree[i] = self.ranks[l]
            return
        mid = (l + r) >> 1
        self.build(2 * i, l, mid)
        self.build(2 * i + 1, mid + 1, r)
        self.pushup(i)

    def update(self, i, x, l, r, k):
        if l == r:
            self.tree[i] = k
            return
        mid = (l + r) >> 1
        if x <= mid:
            self.update(2 * i, x, l, mid, k)
        else:
            self.update(2 * i + 1, x, mid + 1, r, k)
        self.pushup(i)

    def query(self, i, x, l, r):
        if l == r: return l
        mid = (l + r) >> 1
        if x <= self.tree[2 * i]: return self.query(2 * i, x, l, mid)
        else: return self.query(2 * i + 1, x, mid + 1, r)

