class UnionFind:
    def __init__(self):
        self.parent = {}
        self.rank = {}
        self.intervals = {}

    def find(self, node):
        if node not in self.parent:
            self.parent[node] = node
            self.rank[node] = 0
            self.intervals[node] = node
            node_info = node
        else:
            root = self.find(self.parent[node])
            if node_info := self.intervals[node]:
                self.intervals[root] = node_info
        return self.parent[node]

    def union(self, node1, node2):
        root1 = self.find(node1)
        root2 = self.find(node2)

        if root1 != root2:
            if self.rank[root1] < self.rank[root2]:
                self.parent[root1] = root2
                node_info = self.intervals[node1]
                if interval := self.intervals[root2]:
                    start, end = min(interval[0], node_info[0]), max(interval[1], node_info[1])
                    self.intervals[root2] = [start, end]
                else:
                    self.intervals[root2] = node_info
            elif self.rank[root1] > self.rank[root2]:
                self.parent[root2] = root1
                node_info = self.intervals[node2]
                if interval := self.intervals[root1]:
                    start, end = min(interval[0], node_info[0]), max(interval[1], node_info[1])
                    self.intervals[root1] = [start, end]
                else:
                    self.intervals[root1] = node_info
            else:
                self.parent[root2] = root1
                self.rank[root1] += 1
                node_info = self.intervals[node1]
                if interval := self.intervals[root1]:
                    start, end = min(interval[0], node_info[0]), max(interval[1], node_info[1])
                    self.intervals[root1] = [start, end]
                else:
                    self.intervals[root1] = node_info


