def boyer_moore_horspool(haystack, needle):
    """Search for the first occurrence of needle in haystack."""
    n, m = len(haystack), len(needle)
    bad_chars = {c: n for c in needle}
    for i in range(m - 1, 0, -1):
        bad_chars[needle[i]] = m - 1 - i
    shift = m - 1
    while shift <= n:
        s = n - shift
        index = m - 1
        while index >= 0 and haystack[s] == needle[index]:
            s, index = s - 1, index - 1
            if index == -1:
                return s + 1
        if s in bad_chars:
            shift += max(m - index - bad_chars[haystack[s]], 0)
        else:
            break
    return -1

