def binary_search(lst, target, target_value):
    left, right = 2, len(lst) - 1
    mid = (left + right) // 2
    while left <= right:
        mid = (left + right) // 2
        if lst[mid] == target_value:
            if mid == 1:
                return [0, mid]
            elif mid == len(lst) - 1:
                return [mid - 1, mid]
            elif lst[mid - 1] == target_value and lst[mid + 1] == target_value:
                return [mid - 1, mid]
            elif lst[mid - 1] == target_value:
                return [mid - 1, mid]
            else:
                right = mid - 1
        elif lst[mid] < target_value:
            left = mid + 1
        else:
            right = mid - 1

