class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, p):
        if self.parent[p] != p:
            self.parent[p] = self.find(self.parent[p])
        return self.parent[p]

    def union(self, p, q):
        prt, qrt = self.find(p), self.find(q)
        if prt == qrt:
            return False
        if self.rank[prt] < self.rank[qrt]:
            self.parent[prt] = qrt
        elif self.rank[qrt] < self.rank[prt]:
            self.parent[qrt] = prt
        else:
            self.parent[qrt] = prt
            self.rank[prt] += 1
        return True


