def build_graph(intervals):
    nodes = set()
    for start, end in intervals:
        nodes.add(start)
        nodes.add(end)
    nodes = sorted(list(nodes))
    graph = {}
    for i, node in enumerate(nodes):
        graph[i] = []
        for start, end in intervals:
