    n = len(graph)
    dp = [0] * n
    max_len = 0
    for i in range(n):
        for neighbor in graph[i]:
            if neighbor < n:
                dp[i] = max(dp[i], (dp[neighbor] + 1))
            else:
                dp[i] = max(dp[i], (neighbor - i + 1))
        max_len = max(max_len, dp[i])
    return max_len

