            in_degree[i] = 1
            graph[0].append(i)

    def repeat_source_removal():
        queue = deque()
        for i, degree in enumerate(degrees):
            if degree == 0:
                queue.append(i)
            if in_degree[i] == 1 and len(edges[i]) > 0:
                return None

