            return None

        while queue:
            v = queue.popleft()
            for w in edges[v]:
                degrees[w] -= 1
                in_degree[w] += 1
                if degrees[w] == 0 and in_degree[w] == 1:
                    queue.append(w)
                    in_degree[w] = 0
                    graph[len(queue) - 1].append(w)
        return 1

    for _ in range(len(graph)):
        if repeat_source_removal() is None:
            return []

    return graph

