    def __init__(self):
        self.tree = []

    def add(self, start, end):
        self.tree.append((start, end + 1))

    def __merge(self, left, right):
        if not left or not right:
            return left or right
        if left[1] - 1 <= right[0]:
            return left, None
        return left, right

    def __merge_subtree(self, i):
        next_left = i * 2 + 1
        next_right = i * 2 + 2
        if next_left >= len(self.tree):
            return None
        x, next_left = self.__merge_subtree(next_left)
        y, next_right = self.__merge_subtree(next_right)
        return self.__merge(x, y)

    def build(self, intervals):
        self.tree = intervals
        for i in range(len(self.tree) - 1, -1, -1):
            self.tree[i] = self.__merge_subtree(i)

    def query(self, start, end):
        return self.__query(0, start, end, 0, len(self.tree))

    def __query(self, i, start, end, tree_start, tree_end):
        if tree_start >= end or tree_end <= start:
            return None
        elif start <= tree_start and tree_end <= end:
            return self.tree[i]
        next_left = i * 2 + 1
        next_right = i * 2 + 2
        if start < tree_end and tree_start < end:
            return self.__merge(self.__query(next_left, start, end, tree_start, (tree_start + tree_end) // 2), 
                                self.__query(next_right, start, end, (tree_start + tree_end) // 2, tree_end))

