class IntervalTree:
    class Node:
        def __init__(self, start=None, end=None, children=None):
            self.start = start
            self.end = end
            self.children = children if children else []

    def __init__(self):
        self.root = self.Node()

    def merge_intervals(self, intervals):
        if not intervals:
            return []

        self.root = self._build_tree(intervals)

        min_start, max_end = self._extract_min_max(intervals)
        intervals = self._inorder_traversal(self.root, min_start, max_end)

        return intervals

    def _build_tree(self, intervals):
        if not intervals:
            return self.Node()

        start, end = self._find_min_max(intervals, 'start'), self._find_min_max(intervals, 'end')

        mid = (start + end) // 2

        left, right = [], []
        for interval in intervals:
            if interval[0] <= mid:
                left.append(interval)
            else:
                right.append(interval)

        return self.Node(start, end, [
            self._build_tree(left), self._build_tree(right)
        ])

    def _find_min_max(self, intervals, which):
        return min(interval[which] for interval in intervals), max(interval[which] for interval in intervals)

    def _extract_min_max(self, intervals):
        min_start, max_end = float('inf'), float('-inf')
        for start, end in intervals:
            min_start = min(min_start, start)
            max_end = max(max_end, end)
        return min_start, max_end

    def _inorder_traversal(self, node, min_start, max_end):
        intervals = []
        if not node.children:
            return intervals

        for child in node.children:
            intervals.extend(self._inorder_traversal(child, min_start, max_end))

        if min_start <= node.start <= min_start:
            if not intervals or intervals[-1][1] < node.start:
                intervals.append([node.start, node.end])
            else:
                intervals[-1][1] = node.end

            min_start = max(intervals[-1][1] + 1, min_start)

        return intervals


