def merge(left, right, segmented_freq, n, k):
    B = [0] * (k + 1)
    i = j = temp = 0
    freq = freq_seg = [0] * (k + 1)
    while i < n and j < len(left):
        if left[i][0] < right[j][0]:
            freq[left[i][0] + 1] += 1
            i += 1
        elif left[i][0] > right[j][0]:
            freq[right[j][0] + 1] += 1
            j += 1
        else:
            freq_seg[left[i][1]] += left[i][0]
            freq[left[i][0] + 1] += 1
            freq_seg[right[j][1]] += right[j][0]
            freq[right[j][0] + 1] += 1
            i += 1
            j += 1
    while i < n:
        freq_seg[left[i][1]] += left[i][0]
        freq[left[i][0] + 1] += 1
        i += 1
    while j < len(left):
        freq_seg[right[j][1]] += right[j][0]
        freq[right[j][0] + 1] += 1
        j += 1

    while temp <= k:
        B[temp] = segmented_freq[temp]
        for c in range(list(freq.keys())[temp], len(freq)):
            for seg in range(B[temp - 1] if temp > 0 else 0, c):
                freq_seg[seg] += B[temp] * (temp - freq[seg])
            B[temp] += freq[c]
        temp += 1
    return freq_seg

