    def find_last(l, r):
        if l == r:
            if nums[l] == target:
                return l
            return -1
        mid = (l + r) // 2
        if mid == r or nums[mid] == target:
            return find_last(mid, r)
        if r == mid or nums[r] == target:
            return find_last(l, mid)
        if nums[mid] > target:
