def prime_gen(m):
    tb = [0] * (m + 1)
    chislo = []
    p = 2
    while p <= m:
        if tb[p] == 0:
            chislo.append(p)
            for i in range(p, m + 1, p):
                tb[i] = 1
        p += 1
    return chislo

def sieve(n):
    cnt = [0] * (n + 1)
    p2 = 2
    chisla = []
    pri = prime_gen(n)
    for p in pri:
        if p2 == p and p2 * p2 > n:
            break
        elif p2 == p:
            p2 += 1
        elif cnt[p]:
            cnt[p] += 1
            chisla.append(0)
        else:
            cnt[p] += 1
            chisla.append(p)
        for i in range(p, n + 1, p):
            if cnt[i] == 0:
                cnt[i] = 1
                chisla.append(i)
    return chisla

