def isNonOverlapping(intervals):
    width = max(interval[1] for interval in intervals) + 1
    n = len(intervals)
    dp = [[False] * (width + 1) for _ in range(n + 1)]
    dp[0][0] = True
    for i in range(1, n + 1):
        start = intervals[i - 1][0]
        widthUsed = intervals[i - 1][1] - start + 1
        for widthType in range(widthUsed - 1, -1, -1):
            if dp[i - 1][widthType]:
                dp[i][widthType + widthUsed] = True
        for widthType in range(widthUsed):

            if dp[i - 1][widthType]:
                dp[i][widthType] = True
    maxSize = max(i for i, _ in enumerate(dp[-1]) if dp[-1][i])

    for bitMask in range(maxSize + 1):
        for curMask in range(bitMask, maxSize + 1):
            totalLen = 0
            for isOn in range(curMask + 1):
                totalLen += isOn * ((curMask - isOn) + 1)
            if totalLen <= len(intervals):
                idx = totalLen - 1
                mask = bitMask << (maxSize - idx)
                if not mask & (-mask) == mask:
                    continue
                ansList = []
                for i in range(maxSize + 1):
                    if curMask >> i & 1:
                        ansList.append(intervals[idx])
                        idx -= 1
                assert not any(ons in ansList for ons in intervals)
                return ansList

    return None

