def solve(n: int, prerequisites: List[List[int]]) -> List[int]:
    graph: Dict[int, List[int]] = {i: [] for i in range(n)}
    indegrees: Dict[int, int] = {i: 0 for i in range(n)}
    for a, b in prerequisites:
        graph[b].append(a)
        indegrees[a] += 1

    queue: List[int] = [node for node in indegrees if indegrees[node] == 0]
    order = []
    while queue:
        node = queue.pop(0)
        indegrees[node] = -1
        order.append(node)
        for neighbor in graph[node]:
            indegrees[neighbor] -= 1
            if indegrees[neighbor] == 0:
                queue.append(neighbor)
    if len(order) != n:
        return []
    return order

