def solve(n, prerequisites):
    graph = _build_graph(prerequisites)
    graph_preorder = set(i for tasks in prerequisites for i in tasks)
    visited = set()

    for node in range(n):
        if node in visited:
            continue

        if not _dfs(node, graph, visited, graph_preorder, push_to_output):
            return []

    return list(map(graph_preorder.index, push_to_output))

def _dfs(node, graph, visited, graph_preorder, push_to_output):
    if node in push_to_output:
        return True

    if node in visited:
        return False

    visited.add(node)

    for parent in _get_parent_tasks(node, graph):
        if not _dfs(parent, graph, visited, graph_preorder, push_to_output):
            return False

    _remove_parent_tasks(node, graph)
    push_to_output.append(node)

    return True

def matrix_multiply(A, B):
    C = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            for k in range(2):
                C[i][j] += A[i][k] * B[k][j]
    return C

def matrix_power(A, n):
    if n == 1:
        return A
    if n % 2 == 0:
        half_pow = matrix_power(A, n // 2)
        return matrix_multiply(half_pow, half_pow)
    else:
        half_pow = matrix_power(A, n // 2)
        return matrix_multiply(matrix_multiply(half_pow, half_pow), A)

