def solve(nums):
    def get_len(i, memo):
        if i >= len(nums):
            return 0
        if i in memo:
            return memo[i]
        memo[i] = 1 + max(get_len(i + 1, memo), get_len(binary_search(nums, i + 1, nums[i] + 1), memo))
        return memo[i]

    def binary_search(nums, start, val):
        left, right = start, len(nums)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] < val:
                left = mid + 1
            else:
                right = mid
        return left

    return get_len(0, {})

