def insert_recs(nums, recs):
    new_recs = [nums[0]]
    for x in nums[1:]:
        if x >= new_recs[-1]: # If x is greater than or equal to the largest element in new_recs, 
            new_recs.append(x) # insert x at the end of new_recs
        else:
            # Use binary search to find the largest element in new_recs that is less than x
            pos = 0
            while pos < len(new_recs) and new_recs[pos] < x: pos += 1
            new_recs[pos] = x
    return new_recs

