def sorted_stream(iterable):
    """A generator that maintains a sorted list in memory."""
    stack = []
    for item in iterable:
        while stack and item < stack[-1]:
            stack.pop()
        stack.append(item)
    return iter(stack)

def sorted_generator(iterable):
    """A generator that yields items in sorted order, using O(n log n) extra memory."""
    sorted_items = sorted(set(iterable))
    k = len(sorted_items) - k + 1
    for _ in range(k):
        yield sorted_items.pop()

