def return_HELEPER(result, count, n, k):
    total = 0
    for r in range(n, 0, -1):
        nCr_val = nCr(n, r)
        a = min(k, nCr_val)
        diff = max(count[result[r-1]], 0) - max(count.get(result[r-1] - 1, 0), 0)
        if a <= diff:
            p = result[r-1]
            rem = a - 1
        else:
            p = result[r-1] - (a - diff - 1)
            rem = 0
        count[result[r-1]] -= rem
        count[result[r-1]-1] += rem
        total += rem * ((n - r + 1) ** (r-2) * (r-1)) // (r-1)
        if rem == 0: 
            return p

    return sum(count[x] for x in sorted(count))

