def quickselect(nums, k):
    if len(nums) == 1:
        return nums[0]
    pivot = random.choice(nums)
    smaller = [x for x in nums if x < pivot]
    larger_equal = [x for x in nums if x >= pivot]
    m = len(smaller)
    if k <= m:
        return quickselect(smaller, k)
    elif k > len(smaller) + 1:
        return quickselect(larger_equal, k - m - 1)
    else:
        return pivot

