def dfs(graph, n):
    stack = [0] * n
    top = 0
    for i in range(1, n):
        if graph[i] == -1:
            stack[top] = i
            top += 1
    indices = list(range(n))
    indices.sort(key=lambda x: graph[x])
    for i in indices:
        if graph[i] == -1:
            connected = 0
            while top > 0:
                v = stack[top - 1]
                top -= 1
                if connected <= i and v != i:
                    graph[v] = connected
                    connected += 1
    for i in range(1, n):
        if graph[i] == -1:
            connected = 0
            for j in range(i, n):
                if graph[j] == -1:
                    if j > i and connected == 0:
                        connected = connected + 1
                    if graph[indices[j]] == -1:
                        graph[indices[j]] = connected
        elif graph[i] > i:
            graph[i] = i
    return max(graph)

