def ids(i: int, parent: List[int]) -> int:
    if parent[i] != i:
        parent[i] = ids(parent[i], parent)
    return parent[i]

def union(u: int, v: int, parent: List[int]) -> None:
    i = ids(u, parent)
    j = ids(v, parent)
    parent[j] = i

def solve(n: int, edges: List[List[int]]) -> int:
    parent = list(range(n))
    for u, v in edges:
        union(u, v, parent)
    components = set(ids(i, parent) for i in range(n))
    return len(components)

