def convex_hull_topo(graph):
    """Computes the topological sort of a planar graph given its vertices and edges."""
    sta = []
    while graph:
        for src in graph:
            if not graph[src]:
                sta.append(src)
                for neighbor in graph:
                    graph[neighbor].remove(src)
                graph.pop(src)
                break
        if not graph:
            raise ValueError("Cycle detected")
    return sta

