    binSearch = lambda tar:binSearchHelper(0,N-1, prefixEnd, tar)
    def binSearchHelper(low,high,target):
        if low > high:
            return low
        mid = (low+high)//2
        if prefixEnd[mid] <= target:
            return binSearchHelper(mid+1,high,target)
        return binSearchHelper(low,mid-1,target)

