def qsortUtil(arr, low, high, cmp):
    if low == high:
        return low
    pivot = high
    i = low - 1
    temp = arr[pivot]
    arr[pivot] = arr[high]
    arr[high] = temp
    for j in range(low, high):
        if cmp(arr[j], arr[high]) < 0:
            i += 1
            temp = arr[i]
            arr[i] = arr[j]
            arr[j] = temp
    temp = arr[i + 1]
    arr[i + 1] = arr[high]
    arr[high] = temp
    return i + 1

