class PriorityQueue:
    def __init__(self):
        self.queue = []
    def is_empty(self):
        return len(self.queue)==0
    def get_min(self):
        if self.queue:
            return self.queue[0]
        else:
            return None
    def insert(self, data_element):
        self.queue.append(data_element)
        self.heapify_up(len(self.queue)-1)
    def remove_min(self):
        if self.is_empty():
            return None
        if len(self.queue) == 1:
            return self.queue.pop()
        min_value = self.queue[0]
        self.queue[0] = self.queue.pop()
        self.heapify_down(0)
        return min_value
    def heapify_up(self, index):
        parent_index = (index-1)//2
        if index>0 and self.queue[parent_index]>self.queue[index]:
            self.queue[parent_index],self.queue[index] = self.queue[index],self.queue[parent_index]
            self.heapify_up(parent_index)
    def heapify_down(self, index):
        left_child_index = (index*2)+1
        right_child_index = (index *2)+2
        swap_index = index
        if left_child_index < len(self.queue) and self.queue[left_child_index]<self.queue[swap_index]:
            swap_index = left_child_index
        if right_child_index < len(self.queue) and self.queue[right_child_index]<self.queue[swap_index]:
            swap_index = right_child_index
        if swap_index!=index :
            self.queue[index],self.queue[swap_index] = self.queue[swap_index],self.queue[index]
            self.heapify_down(swap_index)

