from typing import List

def solve(n: int, prerequisites: List[List[int]]) -> List[int]:
    def hasCycle(visited, stack, graph):
        for x in visited:
            if visited[x]:
                if stack[x]:
                    return True
            else:
                if hasCycle(visited, {x: True}, graph.get(x, [])):
                    return True
        return False

    graph = [[] for _ in range(n)]
    matrix = [[] for _ in range(n)]
    for a, b in prerequisites:
        graph[b].append(a)

    inDegree = [0] * n
    for i in range(n):
        for j in graph[i]:
            matrix[i].append(0)
            matrix[j].append(1)
            inDegree[i] += 1

    for i in range(n):
        matrix[i].append(1)
        matrix[i].extend([-1 if j == n else j for j in range(n)])

    visited = {i: False for i in range(n)}
    stack = {i: False for i in range(n)}

    for i in range(n):
        hasCycle(visited, stack, graph)

    queue = [i for i in range(n) if inDegree[i] == 0]

    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)

        for v in graph[u]:
            inDegree[v] -= 1
            if inDegree[v] == 0:
                queue.append(v)

    if len(result) != n:
        return []
    return result

