        l, r = 0, len(nums)
        while l < r:
            m = l + (r - l) // 2
            if nums[m] < target:
                l = m + 1
            else:
                r = m
        return l

    def find_last(nums, target):
        l, r = 0, len(nums)
        while l < r:
            m = l + (r - l) // 2
            if nums[m] <= target:
                l = m + 1
            else:
                r = m
        return l - 1

    first = find_first(nums, target)
    last = find_last(nums, target)
    return [first, last] if 0 <= first <= last < len(nums) else [-1, -1]

def solve(nums, target):
    def bs(low, high, bias=False, is_last=False):
        if low > high: return low
        mid = (low + high) // 2
        if nums[mid] == target:
            if bias or mid == 0 or nums[mid - 1] != target:
                return mid
            elif not is_last:
                return bs(low, mid - 1, True, False)
            else:
                return bs(mid + 1, high, True, True)
        elif nums[mid] > target:
            return bs(low, mid - 1, bias, is_last)
        else:
            return bs(mid + 1, high, bias, is_last)

    first = bs(0, len(nums) - 1)
    if first == len(nums):
        return [-1, -1]
    last = bs(first, len(nums) - 1, is_last=True)
    return [first, last]

def low(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return left

def high(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] > target:
            right = mid - 1
        else:
            left = mid + 1
    return right

