def bisect_left(nums, target):
    """Finds the insertion point for target in nums to maintain sorted order"""
    left, right = 0, len(nums)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

def bisect_right(nums, target):
    """Finds the rightmost insertion point for target in nums to maintain sorted order"""
    left, right = 0, len(nums)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] <= target:
            left = mid + 1
        else:
            right = mid
    return left

def solve(nums, target):
    left = bisect_left(nums, target)
    right = bisect_right(nums, target)
    return [-1, -1] if left == right else [left, right - 1]

