def solve(nums, target):
    def helper(nums, target, fn):
        left, right = 0, len(nums) - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                new_left, new_right = fn(mid, nums[mid])
                left, right = max(left, new_left), min(right, new_right)
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return [result, right if result else left]

    def get_boundary(left, right):
        while left > 0 and nums[left - 1] == target:
            left -= 1
        while right < len(nums) - 1 and nums[right + 1] == target:
            right += 1
        return left, right

    return helper(nums, target, get_boundary)

