def merge(precomputations_left, precomputations_right, precomputations_threshold):
    keys_left, freq_left = precomputations_left
    keys_right, freq_right = precomputations_right
    prev_end_threshold_left = precomputations_threshold[0]
    i = prev_end_threshold_left
    j = len(freq_right)
    new_keys = []
    new_freq = [0]

    while i > -1 and j > 0:
        if i == -1:
            new_keys.extend(keys_right[:j])
            new_freq[0] += sum(freq_right[:j])
            prev_end_threshold_left = -1
            j = 0
        elif j == 0:
            new_keys.append(keys_left[i])
            new_freq[0] += freq_left[i]
            i = -1
        elif freq_left[i] == freq_right[j-1]:
            new_keys.append(keys_left[i])
            new_freq[0] += freq_left[i]
            i -= 1
            j -= 1
        elif freq_left[i] > freq_right[j-1]:
            new_keys.append(keys_left[i])
            new_freq[0] += freq_left[i]
            i -= 1
        else:
            new_keys.append(keys_right[j-1])
            new_freq[0] += freq_right[j-1]
            j -= 1

    return new_keys, new_freq

def build_precomputations(solution_counts):
    if len(solution_counts) <= 7:
        return list(solution_counts.keys()), list(solution_counts.values())
    m = len(solution_counts) // 2
    keys_left, freq_left = build_precomputations({k: v for k, v in solution_counts.items()[:-m]})
    keys_right, freq_right = build_precomputations({k: v for k, v in solution_counts.items()[-m:]})
    keys_merged, freq_merged = merge(keys_left, keys_right, build_precomputations({k: v for k, v in solution_counts.items()[:-m-1]}))
    return keys_merged, freq_merged

class Solution:
    def __init__(self, k):
        self.k = k

    def count_frequency(self, nums):
        counter = {}
        for num in nums:
            if num in counter:
                counter[num] += 1
            else:
                counter[num] = 1
        return counter

    def precompute(self, nums):
        counter = self.count_frequency(nums)
        keys, freq = build_precomputations(counter)
        return [x for x in keys if freq[keys.index(x)] >= self.k]

    def quicksearch(self, nums):
        precomputed = self.precompute(nums)
        original = self.count_frequency(nums)
        final = []
        for num in precomputed:
            if original[num] >= self.k:
                final.append(num)
            else:
                break
        return final

    def solve(self, nums):
        return self.quicksearch(nums)

