class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, p):
        if p != self.parent[p]:
            self.parent[p] = self.find(self.parent[p])
        return self.parent[p]

    def union(self, p, q):
        root_p, root_q = self.find(p), self.find(q)
        if root_p != root_q:
            self.parent[root_p] = root_q


def solve(nums, k):
    count = Counter(nums)
    sorted_count = sorted(count.items(), key=lambda x: (-x[1], x[0]))
    uf = UnionFind(len(count))
    for i, (_, freq_i) in enumerate(sorted_count):
        for j, (_, freq_j) in enumerate(sorted_count):
            if freq_j < freq_i:
                uf.union(i, j)
    comp = defaultdict(list)
    for i, (num, freq) in sorted_count:
        comp[uf.find(i)].append(num)
    freq = Counter(num for c in comp.values() for num in c)
    sortedComp = sorted(comp.items(), key=lambda x: (-len(x[1]), x[1][0]))
    ans = []
    for _, nums_c in sortedComp:
        for num in nums_c:
            if k == 0:
                break
            ans.append(num)
            k -= 1
    return ans

