    ng = len(maxheap)
    while ng < k:
        tmp = heapq.heappushpop(maxheap, (-counter.__getitem__(key), key))
        if tmp[0] != -counter.__getitem__(key): counter[key] += 1
        else:
            del key
            key = tmp[1]
