def lengthOfLIS(nums):
    def lengthOfLISHelper(n, memo):
        if n in memo: return memo[n]
        res = 1
        for i in range(len(nums)):
            if i != n and abs(n - i) > 1 and nums[i] < nums[n]:
                res = max(res, lengthOfLISHelper(i, memo) + 1)
        memo[n] = res
        return res

    if not nums: return 0
    max_val = max(nums)
    memo = {i: 1 for i in range(len(nums))}
    for i in range(len(nums)):
        max_val = max(max_val, lengthOfLISHelper(i, memo))
    return max_val

def solve(nums):
    return lengthOfLIS(nums)

