def find_kth_most_common(nums, k):
    count = most_common_count(Counter(nums))
    left, right = -1, 10**10
    while right - left > 1:
        mid = (left + right) // 2
        if len(nums) - sum(x > mid for x in Counter(nums).values()) >= k:
            right = mid
        else:
            left = mid
    return any_to_most_common([x for x in nums if Counter(nums)[x] > right])

