def solve(nums, target):
    def lower_bound(lo=0, hi=None):
        if not nums:
            return None
        if hi is None:
            hi = len(nums) - 1
        if lo == hi:
            return lo if nums[lo] >= target else None
        mid = (lo + hi) // 2
        if nums[mid] > target:
            return lower_bound(lo, mid)
        return lower_bound(mid, hi)

    def upper_bound(lo=0, hi=None):
        if not nums:
            return None
        if hi is None:
            hi = len(nums) - 1
        if lo == hi:
            return lo if nums[lo] <= target else None
        mid = (lo + hi) // 2
        if nums[mid] < target:
            return upper_bound(mid, hi)
        return upper_bound(lo, mid)

    lo = lower_bound(target)
    if lo is None or nums[lo] != target:
        return [-1, -1]
    return [lo, upper_bound(target) - 1]

