from functools import lru_cache

def solve(nums):
    @lru_cache(None)
    def f(i, j):
        if i == j: return 1
        if nums[i] == nums[j]: return f(i + 1, j)
        res = f(i + 1, j) if i + 1 <= j else 0
        res = max(res, f(i, j - 1))
        return 1 + max(res,
                      f(i + 1, j - 1) if nums[i + 1] < nums[j] else 0)

    return min((f(0, i) for i in range(len(nums))),
               default=len(nums))

