def heapify(nums, i, n):
    left_child = 2 * i + 1
    right_child = 2 * i + 2
    smallest = i
    if left_child < n and nums[i] > nums[left_child]:
        smallest = left_child
    if right_child < n and nums[smallest] > nums[right_child]:
        smallest = right_child
    if smallest != i:
        nums[i], nums[smallest] = nums[smallest], nums[i]
        heapify(nums, smallest, n)

