def groupby(iterable, key):
    it = iter(iterable)
    curr = next(it)
    keyval = key(curr)
    group = [(curr, keyval)]
    for item in it:
        k = key(item)
        if k == keyval:
            group.append((item, keyval))
        else:
            yield group
            group = [(item, k)]
            keyval = k
    yield group

