class Bucket:
    def __init__(self, low, high):
        self.low = low
        self.high = high
        self.count = 0
        self.children = [None, None]

def build_bucket(low, high, mid, buckets):
    if low == high:
        buckets[mid] = Bucket(low, high)
        return
    mid = (low + high) // 2
    build_bucket(low, mid, 2 * mid + 1, buckets)
    build_bucket(mid + 1, high, 2 * mid + 2, buckets)
    buckets[mid] = Bucket(low, high)
    buckets[mid].children = buckets[2 * mid + 1], buckets[2 * mid + 2]

def insert(num, bucket):
    if not bucket:
        return
    if num <= bucket.low:
        if not bucket.children[0]:
            bucket.children[0] = Bucket(bucket.low, num)
        insert(num, bucket.children[0])
    else:
        if not bucket.children[1]:
            bucket.children[1] = Bucket(num, bucket.high)
        insert(num, bucket.children[1])
    bucket.count += 1

def search(buckets, k, row, col):
    if not buckets[col]:
        return False
    if buckets[col].count >= k:
        return True
    if row % 2 == 0:
        return search(buckets, k, row, 2 * col + 1) or search(buckets, k, row, 2 * col + 2)
    res = search(buckets, k - buckets[col].count, row, 2 * col + 1)
    if res:
        return True
    return search(buckets, k, row, 2 * col + 2)

