        g[a].append(b)
        indegree[b] += 1

    q = deque([i for i in range(n) if indegree[i] == 0])
    order = []

    while q:
        a = q.popleft()
        order.append(a)
        for b in g[a]:
            indegree[b] -= 1
            if indegree[b] == 0:
                q.append(b)

    if len(order) != n:
        return []

    return order

