def nth_element(nums: list[int], k: int) -> int:
    def _quickselect(low: int, high: int) -> int:
        if low == high:
            return nums[low]

        pivot_index = random.randint(low, high)
        pivot_index = partition(low, high, pivot_index)
        if k == pivot_index + 1:
            return nums[pivot_index]
        elif k < pivot_index + 1:
            return _quickselect(low, pivot_index - 1)
        else:
            return _quickselect(pivot_index + 1, high)

    def partition(low: int, high: int, pivot_index: int) -> int:
        pivot = nums[pivot_index]
        nums[pivot_index], nums[high] = nums[high], nums[pivot_index]
        store_index = low

        for i in range(low, high):
            if nums[i] < pivot:
                nums[i], nums[store_index] = nums[store_index], nums[i]
                store_index += 1

        nums[high], nums[store_index] = nums[store_index], nums[high]
        return store_index

