def nth_element(nums: list[int], k: int) -> int:
    def _quickselect(low: int = 0,
                     high: int = None) -> None:
        if high is None:
            high = len(nums) - 1
        if low == high:
            return
        pivot_index = _partition(low,
                                high)
        if pivot_index == k - 1:
            return
        elif pivot_index < k - 1:
            _quickselect(pivot_index + 1,
                         high)
        else:
            _quickselect(low,
                         pivot_index - 1)

    def _partition(low: int,
                   high: int) -> int:
        pivot = random.choice(nums[low:high + 1])
        left = [num for num in nums[low:high + 1] if num < pivot]
        middle = [num for num in nums[low:high + 1] if num == pivot]
        right = [num for num in nums[low:high + 1] if num > pivot]
        nums[low:high + 1] = left + middle + right
        return len(left)

    _quickselect()
    return nums[k - 1]

