def quickselectCandidate(lo: list[int], hi: list[int], start: int, end: int, k: int) -> int:
    if start == end:
        return lo[start] if hi[start] >= k else hi[start] - 1
    pivot = partition(lo + hi, start, end)
    p = pivot[end - start]
    i = start
    while i <= end - start:
        if lo[i - start] == p:
            lo[i - start], lo[start] = lo[start], lo[i - start]
            i -= 1
        i += 1
    pivot = partition(lo + hi, start, end)
    pivot = (lo + hi)[start]
    if k - sum((lo + hi)[start:end]) <= 0:
        return quickselectCandidate(lo, (lo + hi)[start:end], start, start + end - start, k - sum((lo + hi)[start:end]))
    elif k - sum((lo + hi)[start:end]) + sum((lo + hi)[start+end - start - 1:end]) >= len(lo):
        return quickselectCandidate((lo + hi)[start+end - start - 1:end], hi, start + end - start - 1, end, k - sum((lo + hi)[start:end]) + sum((lo + hi)[start+end - start - 1:end]))
    else: 
        return (lo + hi)[start+end - start - 1] 

