from collections import defaultdict, deque

def solve(n, prerequisites):
    graph = defaultdict(list)
    in_degree = [0] * n

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    valid_order = deque()

    for i in range(n):
        if in_degree[i] == 0:
            valid_order.append(i)

    while valid_order:
        task = valid_order.popleft()
        valid_order.append(task)  # to maintain the order in the result

        for neighbor in graph[task]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                valid_order.append(neighbor)

    return [x for x in valid_order] if len(valid_order) == n else []

