import heapq

def solve(nums, k):
    count = defaultdict(int)
    for v in nums:
        count[v] += 1
    sorted_count = sorted(count.items(), key=lambda x: x[1], reverse=True)
    pq = []
    for v, c in sorted_count:
        heapq.heappush(pq, (-c, v))
        if len(pq) > k:
            heapq.heappop(pq)
    return list(map(lambda x: x[1], pq))

