    val_freq = Counter(nums)
    frequencies = sorted(heapq.heapify([(freq, val) for val, freq in val_freq.items()]), reverse=True)
    max_freq = frequencies[0][0]

    def find(k, max_freq):
        return sorted([val for freq, val in frequencies if freq == max_freq][:k])

    max_freq_i = 0
    while max_freq_i < len(frequencies) and frequencies[max_freq_i][0] == max_freq:
        max_freq_i += 1

    if k > max_freq_i:
        return []
    if k > len(frequencies):
        return find(k, max(frequencies, key=lambda x: x[0])[0])
    return find(k, frequencies[k-1][0])

