class dict:
    def keys(self):
        return self.__keys

    def __init__(self):
        self.__keys = []

    def update(self, other):
        for key, value in other.items():
            if key not in self:
                self.__keys.append(key)
            self[key] += value

    def __getitem__(self, key):
        return self[key]

    def items(self):
        return ((key, self[key]) for key in self)

    def get(self, key, default=None):
        return self.get(key, default)

    def __contains__(self, key):
        return key in self.__keys

    def __setitem__(self, key, value):
        if key in self:
            self[key] += value
        else:
            self.__keys.append(key)
            self[key] = value

    def setdefault(self, key, default=None):
        if key not in self:
            self[key] = default
        return self[key]

    def pop(self, key):
        value = self[key]
        del self[key]
        return value

    def popitem(self):
        key = self.__keys.pop()
        del self[key]
        return key, self[key]

    def dict(self):
        return self

