        i0, i1 = sorted_keys[sub_index-1], sorted_keys[sub_index]
        low, high = 0, k
        while low < high:
            mid = (low + high + 1) >> 1
            attempt = 0
            found = False
            idx = bisect.bisect_right(sorted_keys, i0+mid*(i1-i0)//(2+k)) - 1
            for i in range(max(0, idx-1), min(sub_index-1, len(sorted_keys))):
                attempt += freq.get(sorted_keys[i], 0)
                if attempt >= k:
                    found = True
                    break
            if found:
