def solve(nums, k):
    freq = {}

    # count frequency of each number
    for n in nums:
        freq[n] = freq.get(n, 0) + 1

    # push (freq, n) as a tuple to the heap
    heap = [(freq[n], n) for n in freq]

    # use a custom compare function for heap push
    def custom_compare(a, b):
        if a[0] < b[0]:
            return -1
        elif a[0] > b[0]:
            return 1
        else:
            return 0

    # push n to the heap based on frequency
    for i in range(len(nums)):
        heapq.heappush(heap, (freq[nums[i]], nums[i]), 0, custom_compare)

    # pop k-th smallest frequency from heap
    for _ in range(k - 1):
        heapq.heappop(heap)

    # return k-th smallest number
    return heapq.heappop(heap)[1]

