    # Insertion sort
    for i in range(1, len(sorted_keys)):
        key = sorted_keys[i]
        prev_key = sorted_keys[i - 1]
        j = bisect.bisect_left(sorted_keys, key)
        while j > 0 and sorted_keys[j-1] >= prev_key:
            sorted_keys[j], sorted_keys[j-1] = sorted_keys[j-1], sorted_keys[j]
            counts[sorted_keys[j]], counts[sorted_keys[j-1]] = counts[sorted_keys[j-1]], counts[sorted_keys[j]]
            j -= 1
        sorted_keys.insert(j, key)
        counts[key] = heap = []
        for value, i in counts[prev_key]:
            heapq.heappush(heap, (-value, i))
        counts[prev_key] = heap

    return next(item for pair in counts[sorted_keys[k - 1]] for item in (pair,))[0]

