    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    sorted_nums = sorted(counts.keys())

    def prefix_sum(n):
        return sum(counts[key] for key in sorted_nums[:n])

    def kth_smallest():
        left, right = 0, len(sorted_nums)
        while left < right:
            mid = (left + right) >> 1
            if prefix_sum(mid) >= k:
                right = mid
            else:
                left = mid + 1
        return sorted_nums[left - 1]

    return kth_smallest()

