            return nums[p]
        elif k < p + 1:
            return quickselect(left, p - 1, k)
        else:
            return quickselect(p + 1, right, k)

    def heapify(nums, n, k):
        heap = []
        for i in range(min(k, n)):
            heapq.heappush(heap, nums[i])
        for i in range(min(k, n), n):
            current = nums[i]
            while heap and heap[0] - current > 0:
                heapq.heappop(heap)
            heapq.heappush(heap, current)
        result = -heap[0] if heap else None
        return result

    if k <= 200:
        return quickselect(0, len(nums) - 1, k)
    else:
        return heapify(nums, len(nums), k - 1)

