def nearly_sorted(nums, k):
    n, count = len(nums), 0
    for i in range(n):
        for j in range(n - 1, i, -1):
            if nums[j] < nums[j - 1]:
                tmp = nums[j]
                nums[j] = nums[j - 1]
                nums[j - 1] = tmp
                count += 1
            if count == k - 1: return nums[-k]
    return nums[-k]

