def solve_bs(nums, k):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    indices = {}
    keys = [key for key in sorted(counts.keys())]
    for i, key in enumerate(keys):
        indices[key] = i

    less_count = []
    equal_count = []
    for num, count in counts.items():
        if count == 1:
            heapq.heappush(equal_count, (num, indices[num]))
        else:
            less_count.append((num, indices[num]))

    eff_nums = [key for key in sorted(counts.keys())]
    eff_k = k - len(equal_count)

    while eff_k > 0:
        _, idx = heapq.heappop(less_count)
        heapq.heappush(equal_count, (eff_nums[idx], idx))
        eff_k -= 1

    for i in range(len(equal_count)):
        if k - 1 >= i:
            heapq.heappop(equal_count)
        else:
            return equal_count[i][0]

def solve_bisect(nums, k):
