def solve(n, edges):
    used = [False] * n
    count = 0

    def helper(node):
        nonlocal count
        used[node] = True
        for u, v in edges:
            if u == node:
                helper(v)
            elif v == node:
                helper(u)

    for i in range(n):
        if not used[i]:
            count += 1
            helper(i)

    return count

def solve(haystack: str, needle: str) -> int:
    def kmp_tab(t, p):
        l, m = len(t), len(p)
        next_idx = [-1] + [0] * m
        i = j = 0
        while i < l:
            if j == 0 or t[i] == p[j]:
                i += 1
                j += 1
                next_idx[i] = max(j, next_idx[i])
            elif i < l:
                i = next_idx[i] + 1
                j = 0
        return next_idx

    needle_idx = kmp_tab(needle, needle)
    j = 0
    for i in range(len(haystack)):
        while j > 0 and haystack[i] != needle[j]:
            j = needle_idx[j]
        if haystack[i] == needle[j]:
            j += 1
        if j == len(needle):
            return i - j + 1
    return -1

