    return res

def ithdigitexp(n, exp, num_digits):
    if exp == 0:
        return 1
    res = 10 ** (exp - 1) * ithdigitexp(n, exp - 1, num_digits)
    mult = powmod(n, num_digits - 1, 10 ** 9)
    for _ in range(exp - 1):
        res = (res * mult) % 10 ** 9
    return res

