def rabin_karp(haystack, needle):
    def rolling_hash(s):
        result = 0
        for c in s:
            result = 32 * result + ord(c) - ord('a') + 1
        return result

    def match_length(hsh, n, h):
        if len(hsh) < n:
            return -1
        for i in range(len(hsh) - n + 1)[::-1]:
            if hsh[i:i+n] == rolling_hash(h[:n]):
                return i
        return -1

    n_len = len(needle)
    h_len = len(haystack)
    if n_len > h_len:
        return -1
    hsh = rolling_hash(haystack)
    needle_hash = rolling_hash(needle)
    for i in range(h_len - n_len + 1)[::-1]:
        if needle_hash == hsh:
            match = match_length(hsh, n_len, needle)
            if match + i == h_len - n_len:
                return match + i
        if i == 0:
            hsh -= (ord(haystack[i]) - ord('a') + 1) * (32 ** (n_len - 1))
        else:
            hsh = hsh // 32 * 32 - (ord(haystack[i]) - ord('a') + 1)
            hsh += (ord(haystack[i - 1]) - ord('a') + 1) * (32 ** (n_len - 1))
    return -1

