def hash_able(val):
    if isinstance(val, int) or isinstance(val, float):
        return int(magic(val) * 10**9)
    elif isinstance(val, tuple):
        return hash_able(val[0]) ^ hash_able(val[1])
    elif isinstance(val, list):
        seen = {}
        for item in val:
            if item in seen:
                return seen[item]
            seen[item] = 1
        return len(seen)
    return id(val)

