def parents(n):
    parents_list = list(range(n))
    ranks = [0] * n
    def merge(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        if ranks[u_root] < ranks[v_root]:
            parents_list[u_root] = v_root
        elif ranks[u_root] > ranks[v_root]:
            parents_list[v_root] = u_root
        else:
            parents_list[v_root] = u_root
            ranks[u_root] += 1
    def reset(n):
        parents_list[:] = list(range(n))
        ranks[:] = [0] * n
    return reset, merge

