def intersect(starts, ends):
    n = len(starts)
    if n == 0: return []
    starts.reverse()
    ends.reverse()
    ends = [end for _, end in sorted(zip(ends, ranges(n)), reverse=True)]
    pointers = [0] * n
    stack = []
    for i in range(n):
        while stack and starts[i] >= ends[stack[-1]]:
            stack.pop()
        pointers[i] = stack[-1] if stack else -1
        stack.append(i)
    return pointers

