    n = len(graph)
    visited = [False] * n
    no_of_artpoints = 0
    for i in range(n):
        if not visited[i]:
            no_of_artpoints += 1
            stack = [i]
            while stack:
                u = stack.pop()
                if not visited[u]:
                    visited[u] = True
                    for v in range(len(graph[u]) - 1, graph[u][-1], -1):
                        stack.append(graph[u][v])

    return no_of_artpoints

