        self.data = []

    def append(self, value):
        self.data.append(value)
        self.data.sort(reverse=True)

    def pop(self):
        return self.data.pop(0)

def solve(nums, k):
    count = Counter(nums)
    heap = Heap()
    for key, value in count.items():
        heap.append((value, key))

    topk = []
    for _ in range(min(len(heap.data), k)):
        topk.append(heap.pop()[1])

    return topk

def solve(nums, target):
    first = find_first(nums, target)
    last = find_last(nums, target)
    return [first, last]

def find_first(nums, target):
    left, right = -1, len(nums)
    while left < right - 1:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid
        else:
            right = mid
    return left

def find_last(nums, target):
    left, right = -1, len(nums)
    while left < right - 1:
        mid = (left + right) // 2 + 1
        if nums[mid] > target:
            right = mid
        else:
            left = mid
    return right - 1

