def solve(nums, k):
    groups = []
    curr = [nums[0]]
    curr_val = nums[0]
    for i in range(1, len(nums)):
        if nums[i] == curr_val:
            curr.append(nums[i])
        else:
            groups.append(curr)
            curr = [nums[i]]
            curr_val = nums[i]
    groups.append(curr)

    def helper(nums, k):
        num_values = len(set(nums))
        if k > num_values or k < 1:
            return []
        if len(set(nums)) == 1:
            return nums

        freqs = [len(nums)] * num_values
        res = [''] * num_values
        for val in nums:
            freqs[val] -= 1
            res[val] = val

        low = 0
        high = num_values-1

        while k > 0:
            mid = (low + high) // 2
            equal = equalCount(freqs, mid)
            if equal <= k:
                low = mid + 1
                k -= equal
            else:
                high = mid - 1
        return [int(x) for x in res[:low+1] if freqs[int(x)] == freqs[low]]

    r = []
    for subgroup in groups:
        g = sorted(list(set(subgroup)))
        frs = helper(g, k)
        r += [x for x in subgroup if x in frs]

    cntr = Counter(r)
    res = [x for x, y in cntr.most_common() if y == max(cntr.values())]
    return res

def equalCount(freqs, num):
    n = len(freqs)
    res = 0
    for f in freqs:
        if f <= num:
            res += 1
        else:
            return res
    return res

