def solve(nums, k):
    freqs = [count for element, count in Counter(nums).most_common()]
    diff = [freqs[i] - freqs[i-1] for i in range(1, len(freqs))]
    while len(diff) > k:
        if diff[0] < 1:
            diff.pop(0)
        else:
            diff.pop()
    return list(itertools.islice(itertools.count(), k-1, 0, -1))[::-1] + sorted([i + freqs.index(diff[i-1]) for i in range(1, len(diff)+1)])

def solve(nums, target):
    def binary_search_left(nums, target):
        left, right = -1, len(nums) - 1
        while left < right:
            mid = left + (right - left + 1) // 2
            if nums[mid] < target:
                left = mid
            else:
                right = mid - 1
        return left

    def binary_search_right(nums, target):
        left, right = -1, len(nums) - 1
        while left < right:
            mid = left + (right - left) // 2
            if nums[mid] <= target:
                left = mid
            else:
                right = mid - 1
        return left

    left_idx = binary_search_left(nums, target)
    right_idx = binary_search_right(nums, target)
    if left_idx >= 0 and nums[left_idx] == target:
        return [left_idx, right_idx]
    else:
        return [-1, -1]

