def intersect_interval(a, b):
    if a[0] > b[1] or b[0] > a[1]: return False
    return (a[0], max(a[0], b[0])), (min(a[1], b[1]), a[1])

class ModesCount:
    def __init__(self, freq, mode, m):
        self.freq = freq
        self.mode = mode
        self.m = m
        self.match_count = 0
    def __call__(self, i):
        self.match_count += (self.freq[i] == self.m) + (i == self.mode)
        return self.match_count

