def runLength(L):
    n = len(L)
    i = 0
    ans = []
    while i<n:
        val = L[i]
        count = 1
        while i+1 < n and L[i+1] == val:
            i += 1
            count += 1
        ans.append(count)
        i += 1
    return ans

