def msort(a):
    if len(a) <= 1:
        return a
    mid = (len(a) + 1) // 2
    left = msort(a[:mid])
    right = msort(a[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    while left and right:
        if left[-1][0] < right[-1][0]:
            result.append(left.pop())
        else:
            result.append(right.pop())
    result.extend(left)
    result.extend(right)
    return result[::-1]

