    for n in nums:
        freq[n] = freq.get(n, 0) + 1

    # Use -f to simulate a max-heap
    max_freq = [
        (-count, num)
        for num, count in freq.items()
    ]

    heapq.heapify(max_freq)

    for _ in range(len(max_freq) - k):
