def solve(nums, k):
    freq = Counter(nums)

    def get_median(nums):
        nums = sorted(nums)
        n = len(nums)
        if n % 2 == 0:
            return (nums[n // 2 - 1] + nums[n // 2]) / 2
        else:
            return nums[n // 2]

    median = get_median(sorted(freq.values()))
    top_k = []
    for num, count in freq.items():
        top_k.append((count, num, -math.log(0.7 / (1 - 0.7) + 2 * count / (1 + median))))
    heapq.heapify(top_k)
    return sorted([num for _, num, _ in heapq.nlargest(k, top_k)])

