class Heap:
    def __init__(self):
        self.data = []

    def append(self, value):
        self.data.append(value)
        self.data.sort(reverse = True)

    def pop(self):
        return self.data.pop()

    def top(self):
        if self.data:
            return self.data[0]
        return None

def solve(nums, k):
    freq = Counter(nums)
    values = [(freq[x], x) for x in freq]
    h = Heap()
    for f, v in values:
        h.append((f, v))
    top_f = h.top()[0]
    by_freq = {v for f, v in values if f == top_f}
    for _ in range(k-1):
        top_f -= 1
        h.pop()
        while h.top() and h.top()[0] == top_f:
            h.pop()
        by_freq = {v for f, v in values if f >= top_f}
    return list(by_freq)

