def solve3(nums, k):
    freq = {}

    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    samples = [val for val in set(nums)]

    def partition(partition_idx):
        stars = 0
        for i in range(len(samples)):
            if i < partition_idx:
                stars += freq[samples[i]]
        return stars

    def quickselect(left, right, k):
        if left == right:
            return samples[left]

        pivot_index = partition(partition_idx := (left + right) // 2)
        partition_left = left
        partition_right = pivot_index - 1

        while True:
            left_found = False
            while not left_found and partition_left < right:
                if freq[samples[partition_left]] >= freq[samples[k - 1]]:
                    left_found = True
                else:
                    partition_left += 1

            right_found = False
            while not right_found and left < partition_right:
                if freq[samples[k - 1]] <= freq[samples[partition_right]]:
                    right_found = True
                else:
                    partition_right -= 1

            if partition_left <= partition_right:
                samples[partition_left], samples[partition_right] = samples[partition_right], samples[partition_left]
                partition_left += 1
                partition_right -= 1
            else:
                return samples[k - 1]

        return None

    return quickselect(0, len(samples) - 1, k)

