def max_value(nums, k):
    bucket = {}

    for num in nums:
        point = bisect.bisect_left(nums, num)
        if point-1 not in bucket:
            bucket[point-1] = []
        bucket[point-1].append(num)

    pointers = list(bucket.keys())

    def go(phase):
        while len(pointers) > 0:
            point = pointers.pop()
            bucket[point].sort(reverse=phase)
            for i in range(len(bucket[point])):
                if k == 1:
                    return bucket[point][i]
                k -= 1
                if k == 0:
                    return bucket[point][i]
                if i+1 < len(bucket[point]) and k-(i+1) <= len(bucket[point][i+1]):
                    pointers.append(point+i+1)
                    break
                if i+1 < len(bucket[point]) and k-(i+1) >= len(bucket[point][i+1]):
                    return bucket[point][i]
    if k > 0:
        mid = len(nums)//2
        return go(False)
    else:
        return go(True)

def binary_search(nums, k):
    nums.sort()
    l, r = 0, len(nums)-1

    while l <= r:
        mid = (l+r)//2

        if mid+1 >= k:
            r = mid-1
        else:
            l = mid+1

    return nums[l]

