    table = [0] * tablesize
    for i in range(1, num_digits):
        table[i+1] = (powmod(10, i, 10 ** 9) + table[i+1]) % 10 ** 9
    low, high = 0, num_digits
    while high - low > 1:
        mid = (low + high) // 2
        res = ithdigitchapter(i - 1, i, tablesize) + ithdigitindex(i - 1, i, tablesize) + i * ithdigitexp(10, 9, i)
