def interval_coverage(i, prev):
    if not i:
        return 0
    res = float('inf')
    left = 0
    r_mask = (1 << len(i)) - 1
    for right in range(31):
        c_mask = (r_mask ^ ((1 << right) - 1))
        linesCovered = sum(bin(c & prev).count('1') for c in c_mask)
        j = left
        for c in c_mask:
            if c & prev == c:
                continue
            count = bin(c & (r_mask ^ prev)).count('1')
            res = min(res, linesCovered + count * (right + 1 - j))
            j += count
        left = min(left, right + 1)
    return res

