class SortedList:
    def __init__(self, iterable=None):
        self._lists = [sorted(iterable) if iterable else None]

    def _merge_lists(self):
        self._lists = [x for x in self._lists if x is not None and len(x) > 0]
        if len(self._lists) == 1:
            return self._lists[0]
        merged_list = self._lists.pop(0)
        while self._lists:
            next_list = self._lists.pop(0)
            i = j = 0
            while i < len(merged_list) and j < len(next_list):
                if next_list[j] < merged_list[i]:
                    merged_list.insert(i, next_list.pop(j))
                else:
                    i += 1
            merged_list.extend(next_list)
        self._lists = [merged_list]

    def add(self, value):
        list_for_value = next((l for l in self._lists if value in l), None)
        if list_for_value is not None:
            list_for_value.append(value)
        else:
            self._lists.append([value])

    def remove(self, value):
        for l in self._lists:
            if value in l:
                l.remove(value)
                return

    def pop(self, index=-1):
        list_ = self._lists[index % len(self._lists)]
        value = list_.pop()
        if not list_:
            self._lists.pop()
        return value

    def __getitem__(self, index):
        if index < 0:
            index += len(self)
        self._merge_lists()
        return self._lists[0][index]

    def __len__(self):
        self._merge_lists()
        return sum(len(x) for x in self._lists)

    def sort(self, key=None):
        for l in self._lists:
            l.clear()
            l.extend(sorted(self, key=key))

    def reverse(self):
        self._merge_lists()
        self._lists[0].reverse()

