def solve(n, prerequisites):
    graph = [list() for _ in range(n)]
    in_degree = [0] * n
    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    def can_finish():
        sources = deque(i for i in range(n) if in_degree[i] == 0)
        result = list(range(n))
        index = 0

        while sources:
            vertex = sources.pop()
            result[index] = vertex
            index += 1
            for a in graph[vertex]:
                in_degree[a] -= 1
                if in_degree[a] == 0:
                    sources.append(a)
        return index == n

    def remove_node(index):
        for a in graph[index]:
            in_degree[a] -= 1
            if in_degree[a] == 0:
                graph[a].append(index)

    def backtrack(start):
        if can_finish():
            return [start]
        for i in range(start, n):
            if in_degree[i] == 0:
                for j in range(i, start, -1):
                    remove_node(j)
                if can_finish():
                    result = [start] + backtrack(i + 1)
                    for j in range(i, start, -1):
                        graph[j].append(i)
                    return result
                for j in range(i, start, -1):
                    graph[j].remove(i)
                    if j - 1 >= 0:
                        in_degree[j - 1] += 1
                return []
        return [start]

    return backtrack(0) or []

