    def fibslow(m):
        if m == 0:
            return 0
        if m == 1:
            return 1
        return fibslow(m - 1) + fibslow(m - 2)

    def fibfast(m):
        a, b = 0, 1
        for _ in range(2, m + 1):
            a, b = b, a + b
        return a

    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n % 3 == 1:
        return fibslow(n)
    elif n % 3 == 2:
        return fibslow(n - 1)
    else:
        return fibfast(n)

