def mergeOverlapping(intervals):
    if not intervals:
        return []

    intervals = [(intervals[i][0], i, 0) for i in range(len(intervals))] + \
                [(intervals[i][1], i, 1) for i in range(len(intervals))]
    intervals.sort()

    mergeStack = []
    result = []

    for interval in intervals:
        if not mergeStack or mergeStack[-1][2] != 1 or interval[0] > mergeStack[-1][0]:
            mergeStack.append(interval)
        else:
            lastInterval = mergeStack.pop()
            if lastInterval[2] == 0: key, i, _ = lastInterval
