def introsort(nums, max_depth = 2 * len(nums).bit_length()):
    def qselect(k):
        if len(nums) <= 16:
            for i in range(len(nums)):
                if nums[i] == nums[k - 1]:
                    return i
            return k - 1
        pivot = choose_pivot(nums)
        less = [x for x in nums if x < pivot]
        equal = [x for x in nums if x == pivot]
        greater = [x for x in nums if x > pivot]
        if k <= len(less):
            return qselect(k, less, max_depth - 1)
        elif k <= len(less) + len(equal):
            return len(less)
        else:
            return qselect(k - len(less) - len(equal), greater, max_depth - 1)
    def choose_pivot(nums):
        return nums[len(nums) // 2]
    def heapify(nums, i, n):
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2
        if left < n and nums[left] > nums[largest]:
            largest = left
        if right < n and nums[right] > nums[largest]:
            largest = right
        if largest != i:
            nums[i], nums[largest] = nums[largest], nums[i]
            heapify(nums, largest, n)
    def heap_sort(nums):
        n = len(nums)
        for i in range(n // 2 - 1, -1, -1):
            heapify(nums, i, n)
        for i in range(n - 1, 0, -1):
            nums[0], nums[i] = nums[i], nums[0]
            heapify(nums, 0, i)
    def introsort_recursion(nums, k, max_depth):
        if max_depth == 0:
            heap_sort(nums)
        elif len(nums) >= 16:
            pivot = choose_pivot(nums)
            less = [x for x in nums if x < pivot]
            greater = [x for x in nums if x > pivot]
            k.refs = qselect(k, less) + 1
            if k.refs < len(less):
                return introsort_recursion(less, k.refs, max_depth - 1)
            elif k.refs == len(less):
                return pivot
            else:
                return introsort_recursion(greater, k.refs - len(less), max_depth - 1)
        else:
            heap_sort(nums)
    return introsort_recursion(nums, k, max_depth)

def count_sort(arr, k):
    max_val = max(arr)
    min_val = min(arr)
    max_val = min(max_val, max_val + k - 1)
    if max_val == min_val:
        nums = arr[:]
        return nums
    n = max_val - min_val + 1
    count = [0 for _ in range(n)]
    for i in range(len(arr)):
        count[arr[i] - min_val] += 1
    output = []
    for i in range(n):
