    return output

def radix_sort(nums, fl):
    if fl == 'sort':
        max_val = max(nums)
    else:
        one = [i for i in nums if i % 2 == 1]
        zero = [i for i in nums if i % 2 == 0]
        return one if len(one) >= len(zero) else zero
    digits = 1
    while (10 ** digits - 1) <= max_val:
        slots = [0 for _ in range(10)]
        for i in nums:
            slots[(i // digits) % 10] += 1
        for i in range(1, 10):
            slots[i] += slots[i - 1]
        output = [0 for _ in range(len(nums))]
        for i in range(len(nums) - 1, -1, -1):
            output[slots[(nums[i] // digits) % 10] - 1] = nums[i]
            slots[(nums[i] // digits) % 10] -= 1
        nums = output[:]
        digits *= 10
    return nums

