            self._heapify_up(parent)

    def _heapify_down(self, i):
        left = 2 * i + 1
        right = 2 * i + 2
        smallest = i
        if len(self.heap) > left and self.heap[left] < self.heap[smallest]:
            smallest = left
        if len(self.heap) > right and self.heap[right] < self.heap[smallest]:
            smallest = right
        if smallest != i:
