        pivot_count = 1
        if pivot != nums[pivot]:
            pivot_count = 0
        left = start
        right = end
        while left <= right:
            while nums[left] < nums[pivot]:
                left += 1
            while nums[right] > nums[pivot]:
                right -= 1
            if left <= right and nums[right] != nums[pivot]:
                nums[left], nums[right] = nums[right], nums[left]
            if left <= right and nums[left] == nums[pivot]:
                pivot_count += 1
                if pivot_count == k:
                    nums[start], nums[left] = nums[left], nums[start]
                    return left
                left += 1
            if left <= right and nums[right] == nums[pivot]:
                right -= 1
        return left

    def qksort(nums: List[int], start: int, end: int) -> None:
        if start >= end:
            return
        pivot = partition(nums, start, end, end)
        if pivot == k - 1:
            return
        elif pivot > k - 1:
            qksort(nums, start, pivot - 1)
        else:
            qksort(nums, pivot + 1, end)

    nums_copy = sorted(nums)
    qksort(nums, 0, len(nums) - 1)
    return nums_copy[k - 1]

