def kmp_preprocess(pattern):
    """Build the lps[] array for the KMP algorithm."""
    lps = [0] * len(pattern)
    length = 0
    for i in range(1, len(pattern)):
        while length > 0 and pattern[i] != pattern[length]:
            length = lps[length - 1]
        if pattern[i] == pattern[length]:
            length += 1
        lps[i] = length
    return lps

def solve(haystack, needle):
    """Return the index of the first occurrence of the substring needle in haystack."""
    if len(needle) > len(haystack):
        return -1
    if not needle:
        return 0
    needle = needle + "$"
    lps = kmp_preprocess(needle)
    i, j = 0, 0
    while i < len(haystack):
        if haystack[i] == needle[j]:
            i += 1
            j += 1
            if j == len(needle) - 1:
                return i - j
        else:
            if j > 0:
                l = j
                while l > 0 and needle[l] != haystack[i]:
                    l = lps[l - 1]
                if needle[l] == haystack[i]:
                    j = l + 1
                else:
                    j = 0
            else:
                i += 1
    return -1

