def heapify pile, low, high: 
    i = high; j = (high + low) // 2
    while i != j:
        if pile[i] <= pile[j]: break
        pile[i], pile[j] = pile[j], pile[i]
        i = j
        j = (high + low) // 2
    if i != low:
        i = low
        j = (low + (low + 1)) // 2
        while i < j:
            if 2 * i + 2 < high and pile[2 * i + 1] < pile[2 * i + 2] and pile[2 * i + 1] < pile[i]: i = 2 * i + 1
            elif 2 * i + 2 < high and pile[2 * i + 2] <  pile[i]: i = 2 * i + 2
            else: break
            if i < low: pile[i], pile[low] = pile[low], pile[i]; low, i = i, low
        heapify(pile, low, i)
    heapify(pile, j, high)

def heap_push(pile, val):
    if len(pile) == 0: return val
    pile.append(val)
    i = len(pile) - 1
    while i != 0 and pile[(i - 1) // 2] <= pile[i]:
        pile[(i - 1) // 2], pile[i] = pile[i], pile[(i - 1) // 2]
        i = (i - 1) // 2
    return pile

