def merge_intervals(intervals):
    def comp(x, y):
        if x[0] != y[0]:
            return x[0] - y[0]
        else:
            return x[1] - y[1]

    intervals.sort(key=lambda x: x[0])
    result, stack = [], []

    for curr in intervals:
        if not stack or comp(stack[-1], curr) < 0:
            stack.append(curr)
        else:
            stack[-1] = [min(stack[-1][0], curr[0]), max(stack[-1][1], curr[1])]
            while len(stack) > 1 and comp(stack[-2], stack[-1]) <= 0:
                del stack[-2]
            stack.append(curr)

    return stack

def solve(intervals):
    result = merge_intervals(intervals)
    return [[x[0], x[1]] for x in result]

