class RQ:
    def __init__(self):
        self.data_structure = []

    def __ior__(self, events):
        self.data_structure += events
        self.data_structure = [(i, *event) if i != last_i else event for last_i, i, event in zip(self.data_structure, self.data_structure[1:], self.data_structure)]
        self.data_structure = [(event[0], event[1]+event[2], event[2]) for i, *event in sorted(self.data_structure, key=lambda x: (x[0], x[1]))]
        return self

    def __ror__(self, other):
        result = [x for x in other.data_structure if x[1] != 1]
        result = [(x[0], x[2]*x[1], x[1]) for x in result]
        result = [(x[0]+1, x[1], x[2]) for i, x in enumerate(result, 1) if i != 1 or x[0] != result[0][0]]
        return result + [x for x in other.data_structure if x[1] == 1][:1]

