def solve_radix(intervals):
    def func(curr, rev):
        nonlocal indices, SEGTREE
        if not intervals:
            return

        if not rev:
            arr = curr.copy()
        else:
            arr = [i[1] for i in curr]

        for x in SEGTREE:
            if x[0] != -1:
                SEGTREE[x] = x[1]

        def build(curr):
            global SEGTREE

            if len(curr) == 0:
                SEGTREE = [[-1, -1] for _ in range((1 << (len(curr).bit_length())) - 1 + len(curr))]

            else:
                mid = (len(curr)) // 2

                leftbuild = len(curr[:mid])
                rightbuild = len(curr[mid:])

                build(curr[:mid])
                build(curr[mid:])
                for i in range(leftbuild+rightbuild-1,-1,-1):
                    if curr[i][1] >= curr[mid][0]:
                        SEGTREE[i] = [curr[i][0], curr[i][1]]

        if rev:
            build([i for i in curr if i[1] >= i[0]])
        else:
            build(curr)

        indices = [-1]*(1<<31)
        best_idx = -1
        val = -1
        for time, idx in enumerate(range(1<<len(curr).bit_length() - 1, -1, -1)):
            if SEGTREE[idx][0] != -1:
                if rev:
                    if SEGTREE[idx][1] == -1:#this is time
                        best_idx = time
                        arr[best_idx] = SEGTREE[idx][0]
                else:
                    arr[best_idx] = SEGTREE[idx][1]

        if best_idx != -1:
            arr[best_idx] = curr[best_idx][1]
            if rev:
                curr[best_idx] = (curr[best_idx][0], arr[best_idx])
                func(curr, True)
            else:
                func([curr[best_idx]], False)

    curr = [(i[0], i[1]) for i in intervals]
    func(curr, False)

    SEGTREE = [[-1,-1] for _ in range((1 << (len(curr).bit_length())) - 1 + len(curr))]
    arr = [i[1] for i in curr]
    func(arr, True)
    seenidxs = set()
    count = 0
    prev = curr[0]
    for i in curr:
        if i[0] in seenidxs or i != prev:
            count += 1
            prev = i
        else:
