class UnionFind:
    def __init__(self):
        self.parents = {}
        self.union_counts = {}

    def create_set(self, node):
        self.parents[node] = node
        self.union_counts[node] = 1

    def find_set(self, node):
        if self.parents[node] == node:
            return node
        return self.find_set(self.parents[node])

    def union_sets(self, node1, node2):
        set1 = self.find_set(node1)
        set2 = self.find_set(node2)
        if set1 != set2:
            if self.union_counts[set1] <= self.union_counts[set2]:
                self.parents[set1] = set2
                self.union_counts[set2] += self.union_counts[set1]
            else:
                self.parents[set2] = set1
                self.union_counts[set1] += self.union_counts[set2]


