def solve(nums, target):
    def find_first(nums, target):
        left, right = loc = 0 if nums else -1, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            v = nums[mid]
            if v < target:
                left = mid + 1
            elif v > target:
                right = mid - 1
            else:
                if mid == 0 or nums[mid - 1] != target:
                    return mid
                right = mid - 1
        return -1

    def find_last(nums, target):
        left, right = loc = len(nums) if nums else -1, 0 if nums else -1
        while left >= right:
            mid = (left + right) // 2
            v = nums[mid]
            if v < target:
                left = mid - 1
            elif v > target:
                right = mid + 1
            else:
                if mid == len(nums) - 1 or nums[mid + 1] != target:
                    return mid
                left = mid + 1
        return -1

    first = find_first(nums, target)
    last = find_last(nums, target)
    return [first, last] if first != -1 else [-1, -1]

