from heapq import heapify, heappop, heappush

def solve(nums, k):
    counter = Counter(nums)
    queue = []
    for num, freq in counter.items():
        heappush(queue, (-freq, num))
        if len(queue) > k:
            heappop(queue)

    def estimate_median(low=0, high=len(nums), i=0):
        if i == 0:
            return 0
        if low == high - 1:
            if random.random() < 0.5:
                return low
            else:
                return high

        if i == k:
            return low + (high - low) // 2

        left = low + (i - len(queue)) // i
        right = (high - left - 1) // (k - i)

        for _ in range(k - i):
            value = random.randint(i, min(right, high - 1))
            heappush(queue, (-len(list(filter(lambda x: x[1] == nums[value], queue))), value))

        median = heappop(queue)[1]
        queue.insert(0, (-len(list(filter(lambda x: x[1] == median, queue))), median))
        heapify(queue)

        count = len(list(filter(lambda x: x[1] == median, queue)))
        if count > 0 and random.random() < count / (k - i + 1):
            return estimate_median(low, (high + left) // 2, i + 1)
        else:
            return estimate_median(left, high, i + 1)

    _, median = queue[0]
    if k % 2 == 0:
        return estimate_median(0, len(nums), 0)
    else:
        return median

