class Heap:
    def __init__(self):
        self.data = []
        self.count = 0

    def add(self, x):
        self.data.append(x)
        self.count += 1
        self.heapify_up(self.count - 1)

    def heapify_up(self, i):
        while i > 0 and self.data[i] < self.data[(i - 1) // 2]:
            self.data[i], self.data[(i - 1) // 2] = (
                self.data[(i - 1) // 2], self.data[i])
            i = (i - 1) // 2

    def get_min(self):
        if not self.data:
            return None
        return self.data[0]

    def extract_min(self):
        if self.count == 0:
            return None
        result = self.data[0]
        self.count -= 1
        self.data[0] = self.data[self.count]
        self.heapify_down(0)
        return result

    def heapify_down(self, i):
        while True:
            j = 2 * i + 1
            if j >= self.count:
                break
            if j + 1 < self.count and self.data[j + 1] < self.data[j]:
                j += 1
            if self.data[i] <= self.data[j]:
                break
            self.data[i], self.data[j] = (
                self.data[j], self.data[i])
            i = j
            j = 2 * i + 1

