                    sleepy_rectangle[i][j] = sleepy_rectangle[i + 1][j + 1] + 1
                else:
                    sleepy_rectangle[i][j] = 0
        return sleepy_rectangle

    def query(self, l, r):
        if l > r:
            l, r = r, l
        return self.sleepy_to_uncleaned_base[l][r]

