def solve(nums, k):
    def partition(left, right):
        pivot = random.choice(nums[left:right+1])
        i = left
        j = right
        while True:
            while nums[i] < pivot:
                i += 1
            while nums[j] > pivot:
                j -= 1
            if i >= j:
                return i
            nums[i], nums[j] = nums[j], nums[i]
    def quickselect(left, right, k):
        if left == right:
            return nums[left]
        idx = partition(left, right)
        if k <= idx - left + 1:
            return quickselect(left, idx - 1, k)
        else:
            return quickselect(idx + 1, right, k - idx + left - 1)
    return quickselect(0, len(nums) - 1, k)

