            return []
        for x in range(1, A):
            for p in range(2, L + 1):
                if pow(x, p, L) == 0:
                    return [x]
        ceil = A + 1
        while True:
            is_prime = True
            for x in range(2, ceil + 1):
                if not pow(x, L, ceil + 1) == x:
                    is_prime = False
                    break
            if is_prime:
                return [pow(pow(x, -1, L), -1, L) for x in range(2, ceil + 1)]
            ceil = ceil + L
    return solve

