def range_minimum_query(nums):
    n = len(nums)
    min_vals = [0] * (4 * n)
    def update(index, value, start, end, node):
        if start == end:
            min_vals[node] = value
            return
        mid = (start + end) // 2
        if index <= mid:
            update(index, value, start, mid, 2 * node + 1)
        else:
            update(index, value, mid + 1, end, 2 * node + 2)
        min_vals[node] = min(min_vals[2 * node + 1], min_vals[2 * node + 2])
    def query(left, right, node, start, end):
        if left > end or right < start:
            return float('inf')
        if left <= start and end <= right:
            return min_vals[node]
        mid = (start + end) // 2
        return min(query(left, right, 2 * node + 1, start, mid),
                   query(left, right, 2 * node + 2, mid + 1, end))
    for i, num in enumerate(nums):
        update(i, num, 0, n - 1, 0)
    return update, query

