def sieve(max_num):
    primes = [1] * (max_num + 1)
    primes[0] = primes[1] = 0
    for i in range(2, int(max_num ** 0.5) + 1):
        if primes[i]:
            for j in range(i * i, max_num + 1, i):
                primes[j] = 0
    return primes

