def fibonacci_recursive(x, memo=None):
    memo = memo if memo is not None else {}
    if x in memo:
        return memo[x]
    if x == 0 or x == 1:
        return x
    else:
        return fibonacci_recursive(x-1, memo) + fibonacci_recursive(x-2, memo)

