def solve(n, prerequisites):
    graph = defaultdict(list)
    rev_graph = defaultdict(list)
    for u, v in prerequisites:
        graph[u].append(v)
        rev_graph[v].append(u)

    color = 0
    topo = []

    def has_cycle(u, prev_color):
        nonlocal color
        if color == -1:
            return True
        if u in rev_graph:
            nonlocal color
            nonlocal topo
            color += 1
            for v in rev_graph[u]:
                if v not in graph or not has_cycle(v, color):
                    continue
                else:
                    return True
            color -= 1
            top_color = color
            topo.append((u, top_color))
            return False
        else:
            return False

    for u in range(n):
        if u not in graph and not has_cycle(u, -1):
            return []

    topo.extend(sorted(topo, key=lambda x: x[1]))
    assignment = [0] * n
    used = [False] * n
    for i, adj in enumerate(topo):
        u = adj[0]
        assign_color = False
        for j in range(assignment[u]+1, n):
            if not used[j]:
                assignment[u] = j
                assign_color = True
                break
        if not assign_color:
            return []

        for v in graph[u]:
            if assignment[v] >= assignment[u]:
                return []

        used[assignment[u]] = True

    return [assignment[i] for i in range(n)]

