def hasCycleHelper(graph, visited, onStack, node, parent):
    visited.add(node)
    onStack.add(node)
    for child in graph[node]:
        if child not in visited:
            if hasCycleHelper(graph, visited, onStack, child, node):
                return True
        elif child != parent and child in onStack:
            return True
    onStack.remove(node)
    return False

