def solve(n, prerequisites):
    def has_cycle(graph):
        visited = [0] * n
        stack = [0]

        while stack:
            node = stack.pop()
            if visited[node] == 1:
                return True
            if visited[node] == 2:
                continue
            visited[node] = 1
            stack += graph[node]
            for x in graph[node]:
                stack.append(x)
            visited[node] = 2

        return False

    def topological_sort(graph):
        stack = []
        visited = [False] * n

        for i in range(n):
            if not visited[i]:
                stack.append(i)
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for x in (graph[node] if node in graph else []):
                        if visited[x]:
                            return []
                        visited[x] = True
                        stack.append(x)

        return [x for x in range(n) if not visited[x]]

    graph = [[] for _ in range(n)]
    for x, y in prerequisites:
        graph[y].append(x)

    if has_cycle(graph):
        return []
    return topological_sort(graph)

