        left, right = 0, len(nums) - 1
        first = -1
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                if forward and mid == 0 or (mid > 0 and nums[mid-1] != target):
                    first = mid
                    right = mid - 1
                elif not forward and mid == len(nums) - 1 or (mid < len(nums) - 1 and nums[mid+1] != target):
                    first = mid
                    left = mid + 1
                else:
                    left = mid + 1 if forward else mid - 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return first

    order = [True, False]
    for f in order:
        first = search(nums, target, f)
        if first != -1:
            last = search(nums, target, not f)
            return [first, last]
    return [-1, -1]

