class Heap:
    def __init__(self):
        self.heap = []

    def parent(self, i):
        return math.floor((i - 1) / 2)

    def child(self, i):
        return (2 * i) + 1, (2 * i) + 2

    def insert(self, val):
        self.heap.append(val)
        i = len(self.heap) - 1
        while i > 0:
            p = self.parent(i)
            if self.heap[p] >= self.heap[i]:
                break
            self.heap[p], self.heap[i] = self.heap[i], self.heap[p]
            i = p

    def delete(self):
        if len(self.heap) == 0:
            return None
        if len(self.heap) == 1:
            return self.heap.pop()
        root = self.heap[0]
        self.heap[0] = self.heap.pop()
        self.heapify(0)
        return root

    def heapify(self, i):
        mc, mc2 = self.child(i)
        if mc2 < len(self.heap):
            if self.heap[mc] < self.heap[mc2]:
                mc = mc2
        if mc >= len(self.heap):
            return
        elif self.heap[i] < self.heap[mc]:
            self.heap[i], self.heap[mc] = self.heap[mc], self.heap[i]
            self.heapify(mc)

