        idx = len(self.heaps) - 1
        while idx > 0 and self.heaps[idx] < self.heaps[(idx - 1) // 2]:
            self.heaps[idx], self.heaps[(idx - 1) // 2] = self.heaps[(idx - 1) // 2], self.heaps[idx]
