        self._heapify_down()
        return val

    def _heapify_down(self, idx=0):
        heap_size = len(self.heaps)
        child_idx = 2 * (idx + 1) if 2 * (idx + 1) < heap_size else 2 * (idx + 1) - heap_size
        while child_idx < len(self.heaps):
            if child_idx + 1 < len(self.heaps) and self.heaps[child_idx + 1] < self.heaps[child_idx]:
                child_idx += 1
            if self.heaps[idx] < self.heaps[child_idx]:
