        min_heap = []
        for val, freq in count.items():
            if -heap.pop() not in mins or freq + 1 >= mins[mins.index(-heap.pop())]:
                min_heap.append((freq, val))
        min_heap.sort()
        for j, freq in sorted(((i, -freq) for i, freq in enumerate(mins)), key=lambda x: x[1]):
            mins[j] = math.inf
            found = False
            for i, (f, val) in enumerate(min_heap):
                if f + 1 >= freq:
                    mins[j] = val
                    del min_heap[i]
                    if len(min_heap) == j - 1:
                        heapq.heapify(min_heap)
