        for j, freq in sorted(((i, -freq) for i, freq in enumerate(mins)), key=lambda x: x[1]):
            if mins[j] not in heap.heaps and math.inf in heap.heaps:
                j = heap.heaps.index(math.inf)
            mins[j] = math.inf
            found = False
