def union(left, right, group):
    left_gs = most_frequent(left)
    right_gs = most_frequent(right)

    def union_gs(left_gs, right_gs):
        n_lgs = {key: value for key, value in left_gs.items()}
        for key, value in right_gs.items():
            if key in n_lgs: 
                n_lgs[key] = max(n_lgs[key], value)
            else: n_lgs[key] = value
        return n_lgs

    l_matrix, r_matrix, n_matrix = [], [], []
    sorted_groups_l, sorted_groups_r = list(left_gs.items()), list(right_gs.items())

    def enclose(low, high, matrix):
        if low <= high:
            mid = (low + high) // 2
            for g, freq in sorted_groups_l[mid:]: n_matrix.append(freq)
            for g, freq in sorted_groups_r: l_matrix.append(freq)
            for g, freq in sorted_groups_r[mid:]: r_matrix.append(freq)
            for g_list, g_freq_list, r_freq_list in zip(sorted_groups_r, r_matrix, r_matrix):
                yield max([y for x,y in g_freq_list] for x,y in g_list), max([y for x,y in r_freq_list] for x,y in g_list)
            yield from enclose(low, mid - 1, matrix)
            yield from enclose(mid + 1, high, matrix)
        else:
            yield None, None

    frequencies = set()
    for kth, rth in enclose(0, len(left) - 1, None):
        if kth is None:
            frequencies.update(right_gs.values())
        elif rth is None:
            frequencies.update(left_gs.values())
        else:
            frequencies.update(union_gs(left_gs, right_gs).values())

    reversed_frequencies = sorted(frequencies, reverse=True)
    i = max(range(len(reversed_frequencies)), key=lambda x: reversed_frequencies[x])

    return [key for key, value in dict.fromkeys(reversed_frequencies[:i+1]).items()]

