classmax_heap:
    def __init__(self, k):
        self.k = k
        self.data = [None] * k

    def push(self, val):
        if self.data[0] is None:
            self.data[0] = val
            return
        idx = 0
        self.data.append(val)
        while idx < self.k:
            parent = (idx - 1) // 2
            if parent < 0:
                break
            if self.data[idx] < self.data[parent]:
                self.data[idx], self.data[parent] = self.data[parent], self.data[idx]
                idx = parent
            else:
                break

    def pop(self):
        idx = 0
        if self.data[0] is None:
            return None
        while idx < self.k-1:
            first = 2 * idx + 1
            second = first + 1
            if second < len(self.data) and self.data[second] > self.data[first]:
                largest = second
            else:
                largest = first
            if self.data[idx] > self.data[largest]:
                self.data[idx], self.data[largest] = self.data[largest], self.data[idx]
                idx = largest
            else:
                break
        self.data[idx] = self.data.pop()
        while idx:
            parent = (idx - 1) // 2
            if parent < 0:
                break
            if self.data[idx] < self.data[parent]:
                self.data[idx], self.data[parent] = self.data[parent], self.data[idx]
                idx = parent
            else:
                break
        return self.data.pop()

