                k += 1
                i += 1
            while j <= end:
                nums[k] = nums[j]
                k += 1
                j += 1

    if k <= len(nums) // 2 + 1:
        # We're looking for a small value; sort the first k elements
        insertion_sort(nums, 0, k - 1)
