class SortedList():
    def __init__(self):
        self._lists = []

    def add(self, x):
        found = False
        for lst in self._lists:
            it = sorted(lst)+ [x]
            if(len(self._lists) == 1 and len(lst) == 0):
                self._lists = [it]
                return
            if (len(lst) == 0):
                self._lists = [it]+self._lists
                found = True
                break
            try:
                idx = next(i for i, y in enumerate(it) if y > x)
                lst.insert(idx, x)
                found = True
                break
            except StopIteration:
                pass
        if not found:
            self._lists.append([x])

    def __iter__(self):
        return itertools.chain.from_iterable(self._lists)

    def __len__(self):
        return sum(len(lst) for lst in self._lists)

    def find_kth(self, k):
        for lst in self._lists:
            if k <= len(lst):
                return sorted(lst)[k - 1]
            k -= len(lst)
        return None

