    def dfs(i, j, target):
        if j - i == 1 and (nums[i] <= target): return True
        if i >= j: return False
        middle = (i + j) // 2
        if nums[middle - 1] <= target and target < nums[middle]:
            return not dfs(i, middle, target) or not dfs(middle, j, target)
        elif nums[middle - 1] <= target: return not dfs(i, middle, target)
        elif target < nums[middle]: return not dfs(middle, j, target)
        return True

    return nums[k - 1] if dfs(0, len(nums), nums[k - 1]) else nums[k - 1 if k % 2 == 1 else len(nums) - k]

