        le = len(needle)
        lf = len(haystack)

        lps = [0] * le
        j = 0
        i = 1

        while i < le:
            if needle[i] == needle[j]:
                j += 1
                lps[i] = j
                i += 1
            elif j != 0:
                j = lps[j - 1]
            else:
                lps[i] = 0
                i += 1

        i = j = 0

        while i < lf:
            if haystack[i] == needle[j]:
                j += 1
                i += 1

            if j == le:
                return i - j

            elif i < lf and haystack[i] != needle[j]:
                if j != 0:
                    j = lps[j - 1]
                else:
                    i += 1

        return -1

    if len(needle) > len(haystack) or not needle:
        return -1

    return KMPSearch(haystack, needle)

