def solve(nums, k):
    def bag_random_walk(nums, k, bit):
        if k == 1 or not bit:
            return min(nums)
        if len(nums) == 1:
            return nums[0]
        left = []
        right = []
        mid = nums[0]
        for x in nums:
            if mid < x:
                right.append(x)
            elif mid > x:
                left.append(x)
            else:
                left.append(x)
        if k <= len(left):
            return bag_random_walk(left, k, bit // 2)
        elif k > len(left) + len([x for x in nums if x == mid]):
            return bag_random_walk(right, k - len(left) - len([x for x in nums if x == mid]), bit // 2)
        else:
            right_mid = []
            for x in right:
                if x != mid:
                    right_mid.append(x)
            half = bool(random.getrandbits(1)) 
            if half:
                return bag_random_walk(left, k, bit // 2)
            else:
                return bag_random_walk(right_mid, k - len(left) - 1, bit // 2)

    return bag_random_walk(nums, k, len(bin(len(nums))) - 2)

