def solve_counting_sort(nums, k):
    if len(nums) < 1000:
        smallest = min(nums)
        largest = max(nums)
        stretch = largest - smallest
        count = stretch * 5
        dim = int(stretch)
        bucket_size = (dim + count + len(nums) - 1) // len(nums)
        histogram = [0] * (dimension := dim + count + 2)
        smallest = round(smallest * -1)
        for n in nums:
            bucket_index = (n + smallest) // bucket_size
            histogram[bucket_index - 1] += 1
        for idx in range(1, dimension):
            histogram[idx] += histogram[idx - 1]
        sorted_nums = [None] * len(nums)
        for n in nums:
            i = (n + smallest) // bucket_size
            sorted_nums[histogram[i - 1] - 1] = n
            histogram[i] -= 1
        n = len(nums)
        for idx in range(n - 1, 0, -1):
            if sorted_nums[n - 1] > sorted_nums[idx - 1]:
                flag = -1
                for shift in range(n // 2):
                    if sorted_nums[flag - shift] < sorted_nums[idx - 1]:
                        flag = flag - shift
                    else:
                        break
                sorted_nums[flag:idx - 1] = sorted_nums[flag + 1:idx]
                sorted_nums[flag] = sorted_nums[idx - 1]
            n -= 1
        return sorted_nums[k-1]
    else:
        return solve(nums, k)

