import bisect

def solve(nums, k):
    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1
    heap = []
    for num, freq in count.items():
        heapq.heappush(heap, (freq, num))
    for _ in range(k-1):
        freq, num = heapq.heappop(heap)
        freq -= 1
        if freq > 0:
            heapq.heappush(heap, (freq, num))
    most_common, _ = heap[0]
    idx = bisect.bisect_left(sorted(count.keys()), most_common) - 1
    sorted_nums = sorted(count.keys())
    while idx >= 0:
        while idx >= 0 and count[sorted_nums[idx]] == most_common:
            idx -= 1
        if idx >= 0:
            most_common = count[sorted_nums[idx]]
        most_common, _ = heap[0]
    return sorted_nums[idx+1]

def bisect_count(arr, val, default):
    if not arr or val < arr[0]:
        return default
    idx = bisect.bisect_left(arr, val)
    if idx < len(arr) and arr[idx] == val:
        return idx
    return default

